/* ==========================================================================
   Ладога Парк PWA — Design System & Custom CSS
   Luxury Eco-Resort Theme (Dark Slate, Warm Gold, Amber Fire & Glassmorphism)
   ========================================================================== */

:root {
  --bg-dark: #0b100d;
  --bg-card: rgba(22, 34, 27, 0.75);
  --bg-card-border: rgba(230, 161, 92, 0.2);
  --bg-glass: rgba(15, 23, 18, 0.65);

  --primary-amber: #e6a15c;
  --primary-glow: rgba(230, 161, 92, 0.35);
  --accent-gold: #f4c478;
  --accent-green: #34d399;
  --accent-blue: #60a5fa;
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --text-dark: #111827;

  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;

  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-pill: 9999px;

  --shadow-lg: 0 20px 40px -15px rgba(0, 0, 0, 0.7);
  --backdrop-blur: blur(20px);
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-sans);
  line-height: 1.5;
  overflow-x: hidden;
  min-height: 100vh;
}

/* --------------------------------------------------------------------------
   INTERACTIVE DEMO CONTROL BAR (Presentation Mode)
   -------------------------------------------------------------------------- */
.demo-bar {
  background: rgba(11, 16, 13, 0.95);
  border-bottom: 1px solid rgba(230, 161, 92, 0.25);
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(12px);
  padding: 8px 16px;
}

.demo-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.demo-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
}

.badge-live {
  background: linear-gradient(135deg, #ef4444, #dc2626);
  color: white;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-pill);
  letter-spacing: 0.5px;
  animation: pulseGlow 2s infinite;
}

@keyframes pulseGlow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

.demo-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.control-group select {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 0.8rem;
  outline: none;
  cursor: pointer;
}

.btn-demo-subtle {
  background: rgba(230, 161, 92, 0.15);
  color: var(--primary-amber);
  border: 1px solid rgba(230, 161, 92, 0.3);
  padding: 4px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  cursor: pointer;
  transition: var(--transition);
}

.btn-demo-subtle:hover {
  background: rgba(230, 161, 92, 0.3);
}

/* --------------------------------------------------------------------------
   HERO BLOCK ("Живой домик" Video Canvas)
   -------------------------------------------------------------------------- */
.hero-container {
  position: relative;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px;
  overflow: hidden;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.video-wrapper {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.hero-video {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 1.2s ease-in-out;
}

.hero-video.active {
  opacity: 1;
}

.video-overlay-gradient {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    180deg,
    rgba(11, 16, 13, 0.6) 0%,
    rgba(11, 16, 13, 0.4) 40%,
    rgba(11, 16, 13, 0.95) 100%
  );
  z-index: 2;
}

.hero-top-nav {
  position: relative;
  z-index: 5;
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1000px;
  margin: 0 auto;
  width: 100%;
}

.brand-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(15, 23, 18, 0.6);
  backdrop-filter: var(--backdrop-blur);
  border: 1px solid rgba(255, 255, 255, 0.15);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 500;
}

.brand-dot {
  width: 8px;
  height: 8px;
  background-color: var(--accent-green);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--accent-green);
}

.btn-guide-pill {
  background: rgba(230, 161, 92, 0.2);
  color: var(--primary-amber);
  border: 1px solid var(--primary-amber);
  backdrop-filter: var(--backdrop-blur);
  padding: 6px 16px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
}

.btn-guide-pill:hover {
  background: var(--primary-amber);
  color: var(--text-dark);
  box-shadow: 0 0 15px var(--primary-glow);
}

.hero-body {
  position: relative;
  z-index: 5;
  max-width: 800px;
  margin: 40px auto 0 auto;
  width: 100%;
  text-align: center;
}

.season-badge {
  display: inline-block;
  background: rgba(230, 161, 92, 0.15);
  color: var(--accent-gold);
  border: 1px solid rgba(230, 161, 92, 0.3);
  padding: 4px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
  margin-bottom: 12px;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: 2.2rem;
  line-height: 1.2;
  margin-bottom: 10px;
  background: linear-gradient(135deg, #ffffff 40%, var(--accent-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 24px auto;
}

/* Guest Personalized Glass Card */
.guest-card-glass {
  background: var(--bg-card);
  backdrop-filter: var(--backdrop-blur);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  text-align: left;
}

.guest-info {
  display: flex;
  align-items: center;
  gap: 14px;
}

.guest-avatar {
  width: 46px;
  height: 46px;
  background: rgba(230, 161, 92, 0.2);
  border: 1px solid var(--primary-amber);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
}

.guest-greeting {
  display: block;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.guest-room {
  font-size: 1.1rem;
  color: var(--text-main);
}

.guest-dates {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(0, 0, 0, 0.3);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
}

.date-pill {
  display: flex;
  flex-direction: column;
}

.date-label {
  font-size: 0.65rem;
  color: var(--text-muted);
  text-transform: uppercase;
}

.date-pill strong {
  font-size: 0.85rem;
  color: var(--accent-gold);
}

.date-arrow {
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* --------------------------------------------------------------------------
   DYNAMIC TRIGGER BANNER SECTION
   -------------------------------------------------------------------------- */
.trigger-banner-section {
  max-width: 1000px;
  margin: -20px auto 30px auto;
  padding: 0 20px;
  position: relative;
  z-index: 10;
}

.trigger-card {
  background: linear-gradient(135deg, rgba(30, 48, 38, 0.9), rgba(18, 28, 22, 0.9));
  backdrop-filter: var(--backdrop-blur);
  border: 1px solid rgba(230, 161, 92, 0.4);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  animation: slideUp 0.5s ease-out;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}

.trigger-content {
  flex: 1;
  min-width: 260px;
}

.trigger-tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--primary-amber);
  margin-bottom: 4px;
}

.trigger-title {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.trigger-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.btn-trigger-action {
  background: linear-gradient(135deg, var(--primary-amber), var(--accent-gold));
  color: var(--text-dark);
  font-weight: 700;
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  border: none;
  cursor: pointer;
  font-size: 0.9rem;
  transition: var(--transition);
  box-shadow: 0 4px 15px var(--primary-glow);
}

.btn-trigger-action:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--primary-glow);
}

/* --------------------------------------------------------------------------
   CATALOGUE SECTION
   -------------------------------------------------------------------------- */
.catalogue-section {
  max-width: 1000px;
  margin: 0 auto 60px auto;
  padding: 0 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 10px;
}

.section-title {
  font-family: var(--font-serif);
  font-size: 1.8rem;
  color: var(--text-main);
}

.section-sub {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.fiscal-badge-tooltip {
  background: rgba(52, 211, 153, 0.15);
  color: var(--accent-green);
  border: 1px solid rgba(52, 211, 153, 0.3);
  padding: 4px 12px;
  border-radius: var(--radius-pill);
  font-size: 0.75rem;
  font-weight: 600;
}

.category-tabs {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 12px;
  margin-bottom: 24px;
  scrollbar-width: none;
}

.category-tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 18px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: var(--transition);
}

.tab-btn.active, .tab-btn:hover {
  background: rgba(230, 161, 92, 0.2);
  color: var(--primary-amber);
  border-color: var(--primary-amber);
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.product-card {
  background: var(--bg-glass);
  backdrop-filter: var(--backdrop-blur);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: var(--transition);
}

.product-card:hover {
  border-color: rgba(230, 161, 92, 0.4);
  transform: translateY(-4px);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
}

.product-icon {
  font-size: 2.2rem;
  margin-bottom: 12px;
}

.product-title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 6px;

}

.product-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 16px;
  flex-grow: 1;
}

.product-fiscal-name {
  font-size: 0.7rem;
  color: rgba(255, 255, 255, 0.4);
  background: rgba(0, 0, 0, 0.25);
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  margin-bottom: 14px;
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.product-price {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--accent-gold);
}

.btn-add-cart {
  background: rgba(230, 161, 92, 0.15);
  color: var(--primary-amber);
  border: 1px solid var(--primary-amber);
  padding: 8px 16px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
}

.btn-add-cart:hover {
  background: var(--primary-amber);
  color: var(--text-dark);
}

/* --------------------------------------------------------------------------
   FLOATING CART BAR & DRAWERS
   -------------------------------------------------------------------------- */
.floating-cart-bar {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: calc(100% - 40px);
  max-width: 600px;
  background: rgba(18, 28, 22, 0.95);
  backdrop-filter: blur(16px);
  border: 1px solid var(--primary-amber);
  border-radius: var(--radius-pill);
  padding: 10px 16px;
  z-index: 90;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
  transition: var(--transition);
}

.floating-cart-bar.hidden {
  display: none;
}

.cart-bar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.cart-summary {
  display: flex;
  align-items: center;
  gap: 12px;
}

.cart-count-badge {
  background: var(--primary-amber);
  color: var(--text-dark);
  font-weight: 700;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85rem;
}

.cart-total-price {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
}

.cart-fiscal-hint {
  font-size: 0.65rem;
  color: var(--text-muted);
}

.btn-checkout {
  background: linear-gradient(135deg, var(--primary-amber), var(--accent-gold));
  color: var(--text-dark);
  font-weight: 700;
  border: none;
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  cursor: pointer;
  font-size: 0.9rem;
}

/* DRAWER OVERLAY */
.drawer-overlay, .modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  z-index: 200;
  display: flex;
  justify-content: flex-end;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.drawer-overlay.active, .modal-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.drawer-content {
  width: 100%;
  max-width: 480px;
  background: #111a14;
  height: 100%;
  display: flex;
  flex-direction: column;
  box-shadow: -10px 0 40px rgba(0,0,0,0.8);
}

.drawer-header, .modal-header {
  padding: 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.drawer-close, .modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 1.4rem;
  cursor: pointer;
}

.drawer-body, .modal-body {
  padding: 20px;
  flex: 1;
  overflow-y: auto;
}

.drawer-footer {
  padding: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.3);
}

.cart-item-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.cart-item-info strong {
  display: block;
  font-size: 0.95rem;
}

.cart-item-info span {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.qty-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-qty {
  background: rgba(255, 255, 255, 0.1);
  color: white;
  border: none;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  cursor: pointer;
}

.fiscal-transparency-box {
  background: rgba(52, 211, 153, 0.08);
  border: 1px solid rgba(52, 211, 153, 0.25);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin: 20px 0;
  font-size: 0.8rem;
}

.fiscal-box-title {
  font-weight: 700;
  color: var(--accent-green);
  margin-bottom: 6px;
}

.fiscal-box-note {
  color: var(--text-muted);
  font-size: 0.7rem;
  margin-top: 6px;
}

.payment-methods {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 15px;
}

.pay-option {
  display: flex;
  gap: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.pay-option.active {
  border-color: var(--primary-amber);
  background: rgba(230, 161, 92, 0.1);
}

.btn-pay-submit {
  width: 100%;
  background: linear-gradient(135deg, var(--primary-amber), var(--accent-gold));
  color: var(--text-dark);
  font-weight: 700;
  font-size: 1rem;
  padding: 14px;
  border: none;
  border-radius: var(--radius-pill);
  cursor: pointer;
  margin-top: 10px;
}

/* MODALS */
.modal-overlay {
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.modal-card {
  background: #121c16;
  border: 1px solid rgba(230, 161, 92, 0.3);
  border-radius: var(--radius-md);
  width: 100%;
  max-width: 480px;
  max-height: 90vh;
  overflow-y: auto;
}

.guide-box {
  display: flex;
  gap: 14px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: var(--radius-sm);
  padding: 14px;
  margin-bottom: 12px;
}

.wifi-box {
  background: rgba(230, 161, 92, 0.12);
  border: 1px solid rgba(230, 161, 92, 0.3);
}

.wifi-password-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 6px;
}

.accent-text {
  color: var(--accent-gold);
}

.btn-copy {
  background: rgba(255, 255, 255, 0.15);
  color: white;
  border: none;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  cursor: pointer;
}

.btn-secondary-full, .btn-primary-full {
  width: 100%;
  padding: 12px;
  border-radius: var(--radius-pill);
  font-weight: 700;
  cursor: pointer;
}

.btn-secondary-full {
  background: transparent;
  border: 1px solid var(--text-muted);
  color: var(--text-main);
}

.btn-primary-full {
  background: var(--primary-amber);
  border: none;
  color: var(--text-dark);
}

/* ORM STARS */
.stars-rating-container {
  display: flex;
  justify-content: center;
  gap: 12px;
  font-size: 2.5rem;
  margin: 20px 0;
}

.star-btn {
  cursor: pointer;
  color: rgba(255, 255, 255, 0.2);
  transition: color 0.2s ease;
}

.star-btn.active, .star-btn:hover {
  color: var(--accent-gold);
}

.promo-gift-box {
  background: linear-gradient(135deg, rgba(230, 161, 92, 0.2), rgba(244, 196, 120, 0.1));
  border: 1px dashed var(--accent-gold);
  padding: 16px;
  border-radius: var(--radius-sm);
  margin-top: 16px;
}

.promo-code-display {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--accent-gold);
  letter-spacing: 2px;
  margin: 8px 0;
}

.btn-yandex-maps {
  display: block;
  background: #fc3f1d;
  color: white;
  text-decoration: none;
  font-weight: 700;
  padding: 12px;
  border-radius: var(--radius-pill);
  margin-top: 14px;
}

/* FISCAL DEBUG TABLE */
.fiscal-debug-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 16px;
  font-size: 0.8rem;
}

.fiscal-debug-table th, .fiscal-debug-table td {
  padding: 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  text-align: left;
}

.fiscal-debug-table th {
  color: var(--primary-amber);
}

.alert-box-info, .alert-box-warning {
  padding: 12px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
}

.alert-box-info {
  background: rgba(96, 165, 250, 0.15);
  border: 1px solid rgba(96, 165, 250, 0.3);
  color: #93c5fd;
}

.alert-box-warning {
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.3);
  color: #fcd34d;
}

/* TOASTS */
.toast-container {
  position: fixed;
  top: 70px;
  right: 20px;
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 340px;
}

.toast {
  background: rgba(18, 28, 22, 0.95);
  border-left: 4px solid var(--accent-green);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  box-shadow: 0 10px 25px rgba(0,0,0,0.6);
  backdrop-filter: blur(10px);
  font-size: 0.85rem;
  animation: toastIn 0.3s ease-out;
}

@keyframes toastIn {
  from { opacity: 0; transform: translateX(30px); }
  to { opacity: 1; transform: translateX(0); }
}

.hidden {
  display: none !important;
}

.text-center {
  text-align: center;
}

.mt-3 { margin-top: 12px; }
.mb-3 { margin-bottom: 12px; }

/* Responsive adjustments */
@media (max-width: 600px) {
  .hero-title { font-size: 1.7rem; }
  .guest-card-glass { flex-direction: column; align-items: flex-start; }
  .guest-dates { width: 100%; justify-content: space-between; }
  .demo-bar-inner { flex-direction: column; align-items: flex-start; }
}

