import confetti from "canvas-confetti";
import { CATALOG_ITEMS, LATE_CHECKOUT_ITEM } from "./catalogData.js";
import { cart, renderCartUI } from "./cartManager.js";
import { switchStage } from "./stageManager.js";
import { computeFiscalSummary } from "./fiscalMapper.js";

let currentCategory = "all";
let currentStage = "2";
let currentSeason = "summer";

// Toast Notification Helper
function showToast(message, title = "🔔 Уведомление") {
  const container = document.getElementById("toastContainer");
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.innerHTML = `
    <strong>${title}</strong>
    <p>${message}</p>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.remove();
  }, 4500);
}

// Render Products Grid
function renderProducts(category = "all") {
  const grid = document.getElementById("productsGrid");
  grid.innerHTML = "";

  const filtered = category === "all" 
    ? CATALOG_ITEMS 
    : CATALOG_ITEMS.filter(i => i.category === category);

  filtered.forEach(product => {
    const card = document.createElement("div");
    card.className = "product-card";
    card.innerHTML = `
      <div>
        <div class="product-icon">${product.icon}</div>
        <h3 class="product-title">${product.displayName}</h3>
        <p class="product-desc">${product.desc}</p>
        <div class="product-fiscal-name">🧾 Чек / TravelLine: ${product.fiscalName}</div>
      </div>
      <div class="product-footer">
        <span class="product-price">${product.price.toLocaleString("ru-RU")} ₽</span>
        <button class="btn-add-cart" data-id="${product.id}">
          + Добавить
        </button>
      </div>
    `;
    grid.appendChild(card);
  });

  // Attach Add to Cart Click
  grid.querySelectorAll(".btn-add-cart").forEach(btn => {
    btn.addEventListener("click", () => {
      const item = CATALOG_ITEMS.find(i => i.id === btn.dataset.id);
      if (item) {
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "🛒 Добавлено в корзину");
      }
    });
  });
}

// Render Fiscal Debug Table
function renderFiscalDebugTable() {
  const tbody = document.getElementById("fiscalTableBody");
  tbody.innerHTML = "";

  CATALOG_ITEMS.concat(LATE_CHECKOUT_ITEM).forEach(item => {
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td><span class="season-badge" style="font-size:0.65rem;">${item.category.toUpperCase()}</span></td>
      <td><strong>${item.displayName}</strong></td>
      <td><strong style="color:var(--accent-green);">${item.fiscalName}</strong></td>
    `;
    tbody.appendChild(tr);
  });
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  // 1. Render initial Products & Fiscal Debug Table
  renderProducts("all");
  renderFiscalDebugTable();

  // 2. Subscribe Cart Manager to UI updates
  cart.subscribe(() => renderCartUI(cart, showToast));

  // 3. Stage & Season Switching
  const stageSelector = document.getElementById("stageSelector");
  const seasonSelector = document.getElementById("seasonSelector");

  const handleStageChange = () => {
    currentStage = stageSelector.value;
    currentSeason = seasonSelector.value;
    switchStage(currentStage, currentSeason, (bannerConfig) => {
      if (bannerConfig.actionCategory) {
        // Scroll to category
        const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
        if (catBtn) catBtn.click();
        document.getElementById("catalogueSection").scrollIntoView({ behavior: "smooth" });
      } else if (bannerConfig.actionModal) {
        document.getElementById(bannerConfig.actionModal).classList.add("active");
      } else if (bannerConfig.actionItem === "late-checkout-16") {
        cart.addItem(LATE_CHECKOUT_ITEM);
        document.getElementById("cartDrawer").classList.add("active");
        showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
      }
    });
  };

  stageSelector.addEventListener("change", handleStageChange);
  seasonSelector.addEventListener("change", handleStageChange);
  handleStageChange(); // initial stage 2 setup

  // 4. Category Tabs
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderProducts(currentCategory);
    });
  });

  // 5. Drawer & Modal Toggles
  const cartDrawer = document.getElementById("cartDrawer");
  document.getElementById("openCartBtn").addEventListener("click", () => cartDrawer.classList.add("active"));
  document.getElementById("closeCartBtn").addEventListener("click", () => cartDrawer.classList.remove("active"));

  const guideModal = document.getElementById("guideModal");
  document.getElementById("openGuideBtn").addEventListener("click", () => guideModal.classList.add("active"));
  document.getElementById("closeGuideBtn").addEventListener("click", () => guideModal.classList.remove("active"));

  const fiscalDrawer = document.getElementById("fiscalDebugDrawer");
  document.getElementById("toggleFiscalDebugBtn").addEventListener("click", () => fiscalDrawer.classList.add("active"));
  document.getElementById("closeFiscalDebugBtn").addEventListener("click", () => fiscalDrawer.classList.remove("active"));

  const ormModal = document.getElementById("ormModal");
  document.getElementById("closeOrmBtn").addEventListener("click", () => ormModal.classList.remove("active"));

  // 6. Copy Wi-Fi
  document.getElementById("copyWifiBtn").addEventListener("click", () => {
    const pwd = document.getElementById("wifiPassword").innerText;
    navigator.clipboard.writeText(pwd);
    showToast("Пароль ladoga2026 скопирован в буфер обмена", "📶 Wi-Fi Подключение");
  });

  // 7. Order Payment Submission & Telegram / TravelLine Simulation
  document.getElementById("submitOrderBtn").addEventListener("click", () => {
    if (cart.getItems().length === 0) return;

    const total = cart.getTotalPrice();
    const fiscalSummary = computeFiscalSummary(cart.getItems());
    const fiscalStrings = fiscalSummary.map(f => `${f.fiscalName} (${f.totalPrice} ₽)`).join(", ");

    cartDrawer.classList.remove("active");

    // Toast 1: TravelLine Sync
    showToast(`Оплата ${total} ₽ успешно прошла через СБП! Данные переданы в TravelLine (ОФД чек: ${fiscalStrings})`, "✅ Оплата успешна");

    // Toast 2: Staff Telegram Notification Simulation (after 1 sec)
    setTimeout(() => {
      showToast(`Telegram-бот отправил задачу персоналу: Домик № 4 (Озерный) — ${cart.getItems().map(i => i.displayName).join(", ")}`, "🔔 Уведомление Персонала");
      cart.clear();
    }, 1200);
  });

  // 8. ORM Rating System (Stars 1-5)
  const starBtns = document.querySelectorAll(".star-btn");
  const lowRatingForm = document.getElementById("lowRatingForm");
  const highRatingCard = document.getElementById("highRatingCard");

  starBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      const rating = parseInt(btn.dataset.star);

      starBtns.forEach((b, idx) => {
        if (idx < rating) b.classList.add("active");
        else b.classList.remove("active");
      });

      if (rating <= 3) {
        lowRatingForm.classList.remove("hidden");
        highRatingCard.classList.add("hidden");
      } else {
        lowRatingForm.classList.add("hidden");
        highRatingCard.classList.remove("hidden");

        // Trigger Confetti!
        confetti({
          particleCount: 120,
          spread: 70,
          origin: { y: 0.6 }
        });
      }
    });
  });

  document.getElementById("submitFeedbackBtn").addEventListener("click", () => {
    const text = document.getElementById("feedbackText").value;
    if (!text) return;
    ormModal.classList.remove("active");
    showToast("Ваше сообщение передано лично управляющему базы. Спасибо!", "💬 Отзыв получен");
  });
});

