      <td class="py-2 pr-2">
        <strong class="block text-primary">${item.displayName}</strong>
        <span class="text-[10px] text-on-surface-variant">${item.price} ₽</span>
      </td>
      <td class="py-2">
        <span class="font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded text-[11px]">${item.fiscalName}</span>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (count > 0) {
    headerBadge.innerText = count;
    headerBadge.classList.remove("hidden");
    headerBadge.classList.add("flex");
  } else {
    headerBadge.classList.add("hidden");
    headerBadge.classList.remove("flex");
  }

  document.getElementById("drawerFinalTotal").innerText = `${total.toLocaleString("ru-RU")} ₽`;

  // Render items inside drawer
  const itemsList = document.getElementById("cartItemsList");
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div class="text-center text-on-surface-variant text-xs py-6">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "bg-white p-3 border border-outline-variant/30 rounded-xl flex items-center justify-between";
      row.innerHTML = `
        <div>
          <strong class="text-xs text-primary block">${item.displayName}</strong>
          <span class="text-[10px] text-on-surface-variant">Фискально: ${item.fiscalName}</span>
        </div>
        <div class="flex items-center gap-2">
          <button class="btn-minus w-6 h-6 rounded-full bg-surface-container-high text-xs font-bold" data-id="${item.id}">-</button>
          <span class="text-xs font-bold">${item.quantity}</span>
          <button class="btn-plus w-6 h-6 rounded-full bg-surface-container-high text-xs font-bold" data-id="${item.id}">+</button>
          <strong class="text-xs text-primary ml-1">${(item.price * item.quantity).toLocaleString("ru-RU")} ₽</strong>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => cart.removeItem(b.dataset.id));
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }

  // Render Fiscal Transparency Summary
  const fiscalSummary = computeFiscalSummary(cart.getItems());
  const fiscalContainer = document.getElementById("fiscalItemsSummary");
  fiscalContainer.innerHTML = "";

  if (fiscalSummary.length === 0) {
    fiscalContainer.innerHTML = `<em class="text-[11px] text-on-surface-variant">Позиции не выбраны</em>`;
  } else {
    fiscalSummary.forEach(f => {
      const div = document.createElement("div");
      div.className = "text-[11px]";
      div.innerHTML = `• <strong>${f.fiscalName}</strong> = <strong>${f.totalPrice.toLocaleString("ru-RU")} ₽</strong>`;
      fiscalContainer.appendChild(div);
    });
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  // 1. Render Catalogue & Fiscal Table
  renderFullCatalogue("all");
  renderFiscalDebugTable();

  // 2. Subscribe Cart
  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // 3. Quick Order Add Buttons (.btn-quick-add)
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      const item = CATALOG_ITEMS.find(i => i.id === id) || (id === "late-checkout-16" ? LATE_CHECKOUT_ITEM : null);
      if (item) {
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в заказ`, "🛒 Корзина обновлена");
      }
    });
  });

  // 4. Stage & Season Selector
  const stageSelector = document.getElementById("stageSelector");
  const seasonSelector = document.getElementById("seasonSelector");

  const handleStageChange = () => {
    currentStage = stageSelector.value;
    currentSeason = seasonSelector.value;
    switchStage(currentStage, currentSeason, (bannerConfig) => {
      if (bannerConfig.actionCategory) {
        const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
        if (catBtn) catBtn.click();
        document.getElementById("fullCatalogueList").scrollIntoView({ behavior: "smooth" });
      } else if (bannerConfig.actionModal) {
        openModal(bannerConfig.actionModal);
      } else if (bannerConfig.actionItem === "late-checkout-16") {
        cart.addItem(LATE_CHECKOUT_ITEM);
        openDrawer("cartDrawer");
        showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
      }
    });
  };

  stageSelector.addEventListener("change", handleStageChange);
  seasonSelector.addEventListener("change", handleStageChange);
  handleStageChange();

  // 5. Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => {
        b.classList.remove("bg-primary", "text-white");
        b.classList.add("bg-surface-container-highest", "text-on-surface-variant");
      });
      btn.classList.remove("bg-surface-container-highest", "text-on-surface-variant");
      btn.classList.add("bg-primary", "text-white");

      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // 6. Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.firstElementChild;
    if (child) child.classList.remove("translate-x-full");
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.firstElementChild;
    if (child) child.classList.add("translate-x-full");
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 300);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("opacity-0", "pointer-events-none");
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (el) el.classList.add("opacity-0", "pointer-events-none");
  };

  // Attach Drawers/Modals Event Listeners
  document.getElementById("openCartHeaderBtn").addEventListener("click", () => openDrawer("cartDrawer"));
  document.getElementById("openCartNavBtn").addEventListener("click", () => openDrawer("cartDrawer"));
  document.getElementById("closeCartBtn").addEventListener("click", () => closeDrawer("cartDrawer"));

  document.getElementById("openGuideBtn").addEventListener("click", () => openModal("guideModal"));
  document.getElementById("openGuideNavBtn").addEventListener("click", () => openModal("guideModal"));
  document.getElementById("closeGuideBtn").addEventListener("click", () => closeModal("guideModal"));

  document.getElementById("toggleFiscalDebugBtn").addEventListener("click", () => openDrawer("fiscalDebugDrawer"));
  document.getElementById("closeFiscalDebugBtn").addEventListener("click", () => closeDrawer("fiscalDebugDrawer"));
  document.getElementById("closeOrmBtn").addEventListener("click", () => closeModal("ormModal"));

  // 7. Wi-Fi Copy
  document.getElementById("copyWifiBtn").addEventListener("click", () => {
    const pwd = document.getElementById("wifiPassword").innerText;
    navigator.clipboard.writeText(pwd);
    showToast("Пароль ladoga2026 скопирован", "📶 Wi-Fi Подключение");
  });

  // 8. Order Submission
  document.getElementById("submitOrderBtn").addEventListener("click", () => {
    if (cart.getItems().length === 0) return;

    const total = cart.getTotalPrice();
    const fiscalSummary = computeFiscalSummary(cart.getItems());
    const fiscalStrings = fiscalSummary.map(f => `${f.fiscalName} (${f.totalPrice} ₽)`).join(", ");

    closeDrawer("cartDrawer");

    showToast(`Оплата ${total} ₽ прошла! Чековая запись TravelLine: ${fiscalStrings}`, "✅ СБП Оплата успешна");

    setTimeout(() => {
      showToast(`Telegram-бот уведомил персонал: Домик №4 — ${cart.getItems().map(i => i.displayName).join(", ")}`, "🔔 Персонал уведомлен");
      cart.clear();
    }, 1200);
  });

  // 9. ORM Rating System
  const starBtns = document.querySelectorAll(".star-btn");
  const lowRatingForm = document.getElementById("lowRatingForm");
  const highRatingCard = document.getElementById("highRatingCard");

  starBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      const rating = parseInt(btn.dataset.star);

      starBtns.forEach((b, idx) => {
        if (idx < rating) {
          b.classList.add("text-[#fecc00]");
          b.classList.remove("text-gray-300");
        } else {
          b.classList.remove("text-[#fecc00]");
          b.classList.add("text-gray-300");
        }
      });

      if (rating <= 3) {
        lowRatingForm.classList.remove("hidden");
        highRatingCard.classList.add("hidden");
      } else {
        lowRatingForm.classList.add("hidden");
        highRatingCard.classList.remove("hidden");
        triggerConfetti();
      }
    });
  });

  document.getElementById("submitFeedbackBtn").addEventListener("click", () => {
    const text = document.getElementById("feedbackText").value;
    if (!text) return;
    closeModal("ormModal");
    showToast("Ваше сообщение передано лично управляющему. Спасибо!", "💬 Отзыв получен");
  });

  document.getElementById("fabSupportBtn").addEventListener("click", () => {
    openModal("guideModal");
  });
});

