let activeVideoIndex = 1;

export function switchStage(stageId, season = "summer", onActionClick) {
  const config = STAGE_CONFIGS[stageId];
  if (!config) return;

  // 1. Silky Smooth Cross-fade video logic
  const video1 = document.getElementById("heroVideo1");
  const video2 = document.getElementById("heroVideo2");

  if (video1 && video2) {
    const currentActive = activeVideoIndex === 1 ? video1 : video2;
    const currentInactive = activeVideoIndex === 1 ? video2 : video1;

    currentInactive.src = config.videoPath;
    currentInactive.load();

    const playPromise = currentInactive.play();
    if (playPromise !== undefined) {
      playPromise.then(() => {
        currentInactive.classList.add("active");
        currentActive.classList.remove("active");
        activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
      }).catch(e => {
        console.log("Auto-play prevented or loading:", e);
        currentInactive.classList.add("active");
        currentActive.classList.remove("active");
        activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
      });
    } else {
      currentInactive.classList.add("active");
      currentActive.classList.remove("active");
      activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
    }
  }

  // 2. Update Atmospheric Texts smoothly
  const titleEl = document.getElementById("heroTitle");
  const subtitleEl = document.getElementById("heroSubtitle");

  if (titleEl) titleEl.innerText = config.title;
  if (subtitleEl) subtitleEl.innerText = config.subtitle;

  // 3. Render Floating Luxury Action Button
  const bannerContainer = document.getElementById("triggerBannerContainer");
  if (bannerContainer) {
    bannerContainer.innerHTML = `
      <button id="triggerActionBtn" class="btn-primary-gold" style="width: 100%; max-width: 20rem; margin: 0 auto; padding: 0.875rem 1.25rem;">
        ${config.banner.actionText}
      </button>
    `;

    const actionBtn = document.getElementById("triggerActionBtn");
    if (actionBtn) {
      actionBtn.addEventListener("click", () => {
        if (onActionClick) {
          onActionClick(config.banner);
        }
      });
    }
  }

  // 4. CONTEXTUAL STAGE CONTENT FILTERING
  const saunaSection = document.getElementById("saunaSection");
  const quickOrdersSection = document.getElementById("quickOrdersSection");
  const catalogueSection = document.getElementById("catalogueSection");
  const morningServiceSection = document.getElementById("morningServiceSection");
  const farewellSection = document.getElementById("farewellSection");
  const saunaSectionHeader = document.getElementById("saunaSectionHeader");
  const scrollIndicator = document.getElementById("scrollIndicator");

  // Reset all
  if (saunaSection) saunaSection.classList.add("hidden");
  if (quickOrdersSection) quickOrdersSection.classList.add("hidden");
  if (catalogueSection) catalogueSection.classList.add("hidden");
  if (morningServiceSection) morningServiceSection.classList.add("hidden");
  if (farewellSection) farewellSection.classList.add("hidden");
  if (scrollIndicator) scrollIndicator.style.display = "flex";

  if (stageId === "1" || stageId == 1) {
    // Stage 1: Pre-arrival -> Show Sauna swipable carousel for check-in, Quick Orders, Catalogue
    if (saunaSection) saunaSection.classList.remove("hidden");
    if (quickOrdersSection) quickOrdersSection.classList.remove("hidden");
    if (catalogueSection) catalogueSection.classList.remove("hidden");
    if (saunaSectionHeader) saunaSectionHeader.innerText = "Выберите баню к приезду (Свайп ➔)";
  } 
  else if (stageId === "2" || stageId == 2) {
    // Stage 2: In-Stay -> Show Sauna swipable carousel for evening, Quick Orders, Catalogue
    if (saunaSection) saunaSection.classList.remove("hidden");
    if (quickOrdersSection) quickOrdersSection.classList.remove("hidden");
    if (catalogueSection) catalogueSection.classList.remove("hidden");
    if (saunaSectionHeader) saunaSectionHeader.innerText = "Вечерняя растопка бани (Свайп ➔)";
  } 
  else if (stageId === "3" || stageId == 3) {
    // Stage 3: Morning Departure 09:00 -> NO sauna, NO quick orders! Only morning coffee, late checkout, and taxi!
    if (morningServiceSection) morningServiceSection.classList.remove("hidden");
  } 
  else if (stageId === "4" || stageId == 4) {
    // Stage 4: After Departure -> ZERO MENU, ZERO SAUNA! Pure clean farewell card!
    if (farewellSection) farewellSection.classList.remove("hidden");
    if (scrollIndicator) scrollIndicator.style.display = "none";
  }
}

import { triggerConfetti } from "./confetti.js";
import { CATALOG_ITEMS, LATE_CHECKOUT_ITEM } from "./catalogData.js";
import { cart } from "./cartManager.js";
import { switchStage } from "./stageManager.js";
import { computeFiscalSummary } from "./fiscalMapper.js";

let currentCategory = "all";
let currentStage = "1";
let currentSeason = "summer";

// Toast Notification Helper (Clean Emojis - No ligatures!)
function showToast(message, title = "🔔 Уведомление") {
  const container = document.getElementById("toastContainer");
  if (!container) return;
  const toast = document.createElement("div");
  toast.className = "glass-card p-3 animate-float-in pointer-events-auto";
  toast.style.cssText = "background: rgba(20,31,25,0.95); border: 1px solid rgba(232,165,88,0.5); color: #f3f4f6; border-radius: 1rem; box-shadow: 0 10px 30px rgba(0,0,0,0.8); font-size: 0.75rem; display: flex; align-items: flex-start; gap: 0.625rem; padding: 0.875rem;";
  toast.innerHTML = `
    <span style="font-size: 20px; margin-top: 2px;">✨</span>
    <div>
      <strong style="color: var(--accent-gold); font-weight: 700; display: block; margin-bottom: 0.125rem;">${title}</strong>
      <p style="color: var(--text-muted); line-height: 1.4;">${message}</p>
    </div>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(-10px)";
    toast.style.transition = "all 0.3s ease";
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// Render Full Catalogue Items List
function renderFullCatalogue(category = "all") {
  const listContainer = document.getElementById("fullCatalogueList");
  if (!listContainer) return;
  listContainer.innerHTML = "";

  const filtered = category === "all" 
    ? CATALOG_ITEMS 
    : CATALOG_ITEMS.filter(i => i.category === category);

  filtered.forEach(product => {
    const card = document.createElement("div");
    card.className = "glass-card p-4";
    card.style.cssText = "padding: 1rem; border-radius: 1.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem;";
    card.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.875rem;">
        <div style="width: 3rem; height: 3rem; border-radius: 1rem; background: rgba(232,165,88,0.1); border: 1px solid rgba(232,165,88,0.2); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0;">
          ${product.icon}
        </div>
        <div>
          <h4 style="font-weight: 700; font-size: 0.875rem; color: #f3f4f6; line-height: 1.3;">${product.displayName}</h4>
          <p style="font-size: 11px; color: var(--text-muted); margin-top: 0.125rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">${product.desc}</p>
        </div>
      </div>
      <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 0.5rem; flex-shrink: 0;">
        <span style="font-size: 0.875rem; font-weight: 800; color: var(--accent-gold);">${product.price.toLocaleString("ru-RU")} ₽</span>
        <button class="btn-add-item btn-primary-gold" style="padding: 0.375rem 0.875rem; font-size: 0.75rem;" data-id="${product.id}">
          + Добавить
        </button>
      </div>
    `;
    listContainer.appendChild(card);
  });

  listContainer.querySelectorAll(".btn-add-item").forEach(btn => {
    btn.addEventListener("click", () => {
      const item = CATALOG_ITEMS.find(i => i.id === btn.dataset.id);
      if (item) {
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Добавлено в корзину");
      }
    });
  });
}

// Render Fiscal Debug Table
function renderFiscalDebugTable() {
  const tbody = document.getElementById("fiscalTableBody");
  if (!tbody) return;
  tbody.innerHTML = "";

  CATALOG_ITEMS.concat(LATE_CHECKOUT_ITEM).forEach(item => {
    const tr = document.createElement("tr");
    tr.style.cssText = "border-bottom: 1px solid rgba(232,165,88,0.15); font-size: 0.75rem;";
    tr.innerHTML = `
      <td style="padding: 0.625rem 0.5rem 0.625rem 0;">
        <strong style="display: block; color: #f3f4f6; font-family: var(--font-sans);">${item.displayName}</strong>
        <span style="font-size: 10px; color: var(--text-muted);">${item.price} ₽</span>
      </td>
      <td style="padding: 0.625rem 0;">
        <span style="font-weight: 600; color: #34d399; background: rgba(52,211,153,0.15); border: 1px solid rgba(52,211,153,0.3); padding: 0.125rem 0.5rem; border-radius: 0.375rem; font-size: 11px;">${item.fiscalName}</span>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (headerBadge) {
    if (count > 0) {
      headerBadge.innerText = count;
      headerBadge.classList.remove("hidden");
      headerBadge.style.display = "flex";
    } else {
      headerBadge.classList.add("hidden");
      headerBadge.style.display = "none";
    }
  }

  const finalTotalEl = document.getElementById("drawerFinalTotal");
  if (finalTotalEl) finalTotalEl.innerText = `${total.toLocaleString("ru-RU")} ₽`;

  const itemsList = document.getElementById("cartItemsList");
  if (!itemsList) return;
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 2rem 0;">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "glass-card";
      row.style.cssText = "padding: 0.875rem; border-radius: 1rem; display: flex; align-items: center; justify-content: space-between; border-color: rgba(232,165,88,0.3);";
      row.innerHTML = `
        <div style="padding-right: 0.5rem;">
          <strong style="font-size: 0.75rem; color: #f3f4f6; display: block; line-height: 1.3;">${item.displayName}</strong>
          <span style="font-size: 11px; color: var(--accent-gold); font-weight: 700; margin-top: 0.125rem; display: block;">${item.price.toLocaleString("ru-RU")} ₽ / шт.</span>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
          <button class="btn-minus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">-</button>
          <span style="font-size: 0.75rem; font-weight: 800; width: 1rem; text-align: center;">${item.quantity}</span>
          <button class="btn-plus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">+</button>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => cart.removeItem(b.dataset.id));
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }

  const fiscalSummary = computeFiscalSummary(cart.getItems());
  const fiscalContainer = document.getElementById("fiscalItemsSummary");
  if (fiscalContainer) {
    fiscalContainer.innerHTML = "";
    if (fiscalSummary.length === 0) {
      fiscalContainer.innerHTML = `<em style="font-size: 11px; color: var(--text-muted);">Позиции не выбраны</em>`;
    } else {
      fiscalSummary.forEach(f => {
        const div = document.createElement("div");
        div.style.cssText = "font-size: 11px; color: #34d399;";
        div.innerHTML = `• <strong>${f.fiscalName}</strong>: ${f.totalPrice.toLocaleString("ru-RU")} ₽`;
        fiscalContainer.appendChild(div);
      });
    }
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  renderFullCatalogue("all");
  renderFiscalDebugTable();

  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // Quick Order Add Buttons (.btn-quick-add) for Sauna Carousel & Grid
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      let item = CATALOG_ITEMS.find(i => i.id === id);
      if (id === "late-checkout-16") item = LATE_CHECKOUT_ITEM;
      if (id === "coffee-croissant") {
        item = { id: "coffee-croissant", displayName: "☕ Свежий кофе и круассаны в домик", price: 550, category: "service", fiscalName: "Услуги организации питания в номере" };
      }
      if (item) {
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
      }
    });
  });

  // Toggle Demo Menu Panel
  const toggleDemoBtn = document.getElementById("toggleDemoMenuBtn");
  const demoPanel = document.getElementById("demoMenuPanel");
  if (toggleDemoBtn && demoPanel) {
    toggleDemoBtn.addEventListener("click", () => {
      demoPanel.classList.toggle("hidden");
    });
  }

  // Stage & Season Selector with Full Page Reload & Persistence
  const stageSelector = document.getElementById("stageSelector");
  const seasonSelector = document.getElementById("seasonSelector");

  // Read from URL parameters or localStorage, defaulting to Stage 1!
  const urlParams = new URLSearchParams(window.location.search);
  const savedStage = urlParams.get("stage") || localStorage.getItem("demoStage") || "1";
  const savedSeason = urlParams.get("season") || localStorage.getItem("demoSeason") || "summer";

  currentStage = savedStage;
  currentSeason = savedSeason;

  if (stageSelector) stageSelector.value = currentStage;
  if (seasonSelector) seasonSelector.value = currentSeason;

  // Apply initial stage view
  switchStage(currentStage, currentSeason, (bannerConfig) => {
    if (bannerConfig.actionCategory) {
      const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
      if (catBtn) catBtn.click();
      const catalogEl = document.getElementById("fullCatalogueList");
      if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
    } else if (bannerConfig.actionModal) {
      openModal(bannerConfig.actionModal);
    } else if (bannerConfig.actionItem === "late-checkout-16") {
      cart.addItem(LATE_CHECKOUT_ITEM);
      openDrawer("cartDrawer");
      showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
    }
  });

  const handleStageChange = () => {
    if (!stageSelector || !seasonSelector) return;
    const newStage = stageSelector.value;
    const newSeason = seasonSelector.value;
    localStorage.setItem("demoStage", newStage);
    localStorage.setItem("demoSeason", newSeason);

    // Clean reload to simulate authentic client arrival from the very top!
    window.location.search = `?stage=${newStage}&season=${newSeason}`;
  };

  if (stageSelector && seasonSelector) {
    stageSelector.addEventListener("change", handleStageChange);
    seasonSelector.addEventListener("change", handleStageChange);
  }

  // Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(0)";
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(100%)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 250);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(1)";
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(0.95)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 200);
  };

  // Header Cart Button
  const openCartHeaderBtn = document.getElementById("openCartHeaderBtn");
  const closeCartBtn = document.getElementById("closeCartBtn");
  if (openCartHeaderBtn) openCartHeaderBtn.addEventListener("click", () => openDrawer("cartDrawer"));
  if (closeCartBtn) closeCartBtn.addEventListener("click", () => closeDrawer("cartDrawer"));

  // Guide Modal & Registration Modal Close Buttons
  const closeGuideBtn = document.getElementById("closeGuideBtn");
  if (closeGuideBtn) closeGuideBtn.addEventListener("click", () => closeModal("guideModal"));

  const closeRegBtn = document.getElementById("closeRegBtn");
  if (closeRegBtn) closeRegBtn.addEventListener("click", () => closeModal("regModal"));

  const closeOrmBtn = document.getElementById("closeOrmBtn");
  if (closeOrmBtn) closeOrmBtn.addEventListener("click", () => closeModal("ormModal"));

  // Fiscal Debug Drawer Toggle
  const toggleFiscalBtn = document.getElementById("toggleFiscalDebugBtn");
  const closeFiscalBtn = document.getElementById("closeFiscalDebugBtn");
  if (toggleFiscalBtn) toggleFiscalBtn.addEventListener("click", () => {
    if (demoPanel) demoPanel.classList.add("hidden");
    openDrawer("fiscalDebugDrawer");
  });
  if (closeFiscalBtn) closeFiscalBtn.addEventListener("click", () => closeDrawer("fiscalDebugDrawer"));

  // Online Registration Form Submission
  const submitRegBtn = document.getElementById("submitRegBtn");
  if (submitRegBtn) {
    submitRegBtn.addEventListener("click", () => {
      const phone = document.getElementById("regPhone")?.value;
      if (!phone || phone.trim() === "") {
        showToast("Укажите ваш контактный телефон для связи", "⚠️ Внимание");
        return;
      }
      showToast("✅ Онлайн-регистрация завершена, Ирина! Пропуск на въезд для вашего автомобиля оформлен.", "📋 Добро пожаловать");
      closeModal("regModal");
    });
  }

  // Wi-Fi Copy Button
  const copyWifiBtn = document.getElementById("copyWifiBtn");
  if (copyWifiBtn) {
    copyWifiBtn.addEventListener("click", () => {
      navigator.clipboard.writeText("ladoga2026");
      showToast("Пароль ladoga2026 скопирован в буфер", "📡 Wi-Fi подключение");
    });
  }

  // ORM Interactive Rating Stars
  const stars = document.querySelectorAll(".star-btn");
  const lowForm = document.getElementById("lowRatingForm");
  const highCard = document.getElementById("highRatingCard");

  stars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      stars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });

      if (rating >= 4) {
        if (lowForm) lowForm.classList.add("hidden");
        if (highCard) {
          highCard.classList.remove("hidden");
          highCard.classList.add("animate-fade-in");
        }
        triggerConfetti();
        showToast("Спасибо за вашу высокую оценку!", "🎉 Ладога Парк");
      } else {
        if (highCard) highCard.classList.add("hidden");
        if (lowForm) {
          lowForm.classList.remove("hidden");
          lowForm.classList.add("animate-fade-in");
        }
      }
    });
  });

  // Submit Feedback Button
  const submitFeedbackBtn = document.getElementById("submitFeedbackBtn");
  if (submitFeedbackBtn) {
    submitFeedbackBtn.addEventListener("click", () => {
      const text = document.getElementById("feedbackText")?.value;
      if (!text || text.trim() === "") {
        showToast("Пожалуйста, напишите пару слов о вашем впечатлении", "⚠️ Внимание");
        return;
      }
      showToast("Отзыв отправлен лично управляющему парком. Мы свяжемся с вами!", "🙏 Спасибо за помощь");
      closeModal("ormModal");
    });
  }

  // Order Submission
  const submitOrderBtn = document.getElementById("submitOrderBtn");
  if (submitOrderBtn) {
    submitOrderBtn.addEventListener("click", () => {
      if (cart.getItems().length === 0) {
        showToast("Сначала добавьте услуги в корзину", "🛒 Корзина пуста");
        return;
      }
      const payType = document.querySelector('input[name="payType"]:checked')?.value;
      const total = cart.getTotalPrice();
      if (payType === "sbp") {
        showToast(`Инициирована оплата СБП на сумму ${total.toLocaleString("ru-RU")} ₽. Электронный чек ОФД сформирован.`, "⚡ Оплата СБП");
      } else {
        showToast(`Заказ на сумму ${total.toLocaleString("ru-RU")} ₽ добавлен в ваш фолио TravelLine. Оплата при выезде.`, "🏨 Фолио обновлено");
      }
      cart.clearCart();
      closeDrawer("cartDrawer");
    });
  }

  // Support FAB Button
  const fabSupportBtn = document.getElementById("fabSupportBtn");
  if (fabSupportBtn) {
    fabSupportBtn.addEventListener("click", () => {
      showToast("Связь с консьерж-сервисом Ладога Парк: +7 (812) 555-01-26 (Круглосуточно)", "📞 Консьерж на связи");
    });
  }

  // Call Admin Button inside Guide Modal
  const callAdminBtn = document.getElementById("callAdminBtn");
  if (callAdminBtn) {
    callAdminBtn.addEventListener("click", () => {
      showToast("Набираем номер службы размещения...", "📞 Администратор");
    });
  }
});

/*
 * Ладога Парк | Эко-курорт PWA ("Живой домик")
 * Pure CSS Design System & Hardware Accelerated Animations (Zero CDN dependency!)
 */

:root {
  --bg-dark: #0b110e;
  --bg-card: rgba(18, 28, 23, 0.75);
  --bg-pine: #121c17;
  --bg-pine-light: #1a2820;
  --primary-ember: #e8a558;
  --accent-gold: #f3bc7a;
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --border-ember: rgba(232, 165, 88, 0.25);
  --font-sans: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Cormorant Garamond', Georgia, serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-sans);
  overflow-x: hidden;
  line-height: 1.5;
}

/* 100svh prevents mobile address bar layout jumps */
.hero-container {
  position: relative;
  width: 100vw;
  height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 5rem 1.25rem 2rem;
  overflow: hidden;
}

.video-background-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: hidden;
  background-color: #050806;
}

.hero-video {
  position: absolute;
  top: 50%;
  left: 50%;
  min-width: 100%;
  min-height: 100%;
  width: auto;
  height: auto;
  transform: translate(-50%, -50%) scale(1.02);
  object-fit: cover;
  opacity: 0;
  transition: opacity 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: opacity;
  pointer-events: none;
}

.hero-video.active {
  opacity: 1;
}

.vignette-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(to bottom, rgba(11,17,14,0.65) 0%, rgba(11,17,14,0.1) 30%, rgba(11,17,14,0.4) 75%, rgba(11,17,14,0.95) 100%),
    radial-gradient(circle at center, transparent 40%, rgba(5,8,6,0.65) 100%);
  pointer-events: none;
}

/* Fast, Snappy Appearance (0.3s delay, 0.6s duration) - ADHD Friendly & Responsive! */
.fade-in-delayed {
  opacity: 0;
  animation: fadeInSnappy 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
  will-change: opacity, transform;
}

@keyframes fadeInSnappy {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Glassmorphism Cards */
.glass-card {
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-ember);
  border-radius: 1.25rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.glass-card:hover {
  border-color: rgba(232, 165, 88, 0.45);
}

/* Buttons with NO WRAP guarantee for prices! */
.btn-primary-gold {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-family: var(--font-sans);
  font-weight: 800;
  border: none;
  border-radius: 9999px;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(232, 165, 88, 0.35);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-primary-gold:active {
  transform: scale(0.97);
  box-shadow: 0 2px 10px rgba(232, 165, 88, 0.25);
}

.btn-icon-round {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid var(--border-ember);
  background: rgba(232, 165, 88, 0.15);
  color: var(--accent-gold);
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.btn-icon-round:active {
  transform: scale(0.9);
  background: rgba(232, 165, 88, 0.3);
}

/* Clickable Taxi Phone Button */
.btn-taxi {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: #14221c;
  border: 1px solid rgba(96, 165, 250, 0.3);
  border-radius: 1rem;
  color: #60a5fa;
  text-decoration: none;
  font-size: 0.75rem;
  font-weight: 600;
  transition: all 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-taxi:active {
  background: rgba(96, 165, 250, 0.15);
  transform: scale(0.98);
}

/* Category Tabs */
.tab-btn {
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--bg-pine);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.tab-btn.active {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-weight: 800;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(232, 165, 88, 0.3);
}

/* Modals and Drawers */
.modal-overlay,
.drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100svh;
  background: rgba(5, 8, 6, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.25s ease;
  padding: 1rem;
}

.glass-modal {
  background: #121c17;
  border: 1px solid var(--border-ember);
  border-radius: 1.5rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8);
  max-height: 90svh;
  overflow-y: auto;
}

.drawer-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 100%;
  max-width: 24rem;
  height: 100%;
  background: #121c17;
  border-left: 1px solid var(--border-ember);
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Utilities */
.hidden { display: none !important; }
.opacity-0 { opacity: 0 !important; }
.pointer-events-none { pointer-events: none !important; }
.pointer-events-auto { pointer-events: auto !important; }

@keyframes bounceSlow {
  0%, 100% { transform: translateY(-25%); animation-timing-function: cubic-bezier(0.8,0,1,1); }
  50% { transform: none; animation-timing-function: cubic-bezier(0,0,0.2,1); }
}
.animate-bounce { animation: bounceSlow 2s infinite; }

@keyframes floatIn {
  0% { opacity: 0; transform: translateY(-10px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.animate-float-in { animation: floatIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards; }

