}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (headerBadge) {
    if (count > 0) {
      headerBadge.innerText = count;
      headerBadge.classList.remove("hidden");
      headerBadge.style.display = "flex";
    } else {
      headerBadge.classList.add("hidden");
      headerBadge.style.display = "none";
    }
  }

  const finalTotalEl = document.getElementById("drawerFinalTotal");
  if (finalTotalEl) finalTotalEl.innerText = `${total.toLocaleString("ru-RU")} ₽`;

  const itemsList = document.getElementById("cartItemsList");
  if (!itemsList) return;
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 2rem 0;">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "glass-card";
      row.style.cssText = "padding: 0.875rem; border-radius: 1rem; display: flex; align-items: center; justify-content: space-between; border-color: rgba(232,165,88,0.3); gap: 0.5rem;";
      row.innerHTML = `
        <div style="padding-right: 0.5rem; overflow: hidden;">
          <strong style="font-size: 0.75rem; color: #f3f4f6; display: block; line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.displayName}</strong>
          <span style="font-size: 11px; color: var(--accent-gold); font-weight: 700; margin-top: 0.125rem; display: block;">${item.price.toLocaleString("ru-RU")} ₽ / шт.</span>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
          <button class="btn-minus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">-</button>
          <span style="font-size: 0.75rem; font-weight: 800; width: 1rem; text-align: center;">${item.quantity}</span>
          <button class="btn-plus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">+</button>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => {
        cart.removeItem(b.dataset.id);
        const hasSaunaLeft = cart.getItems().some(i => i.category === "sauna" || i.id.includes("sauna") || i.id.includes("hottub") || i.id.includes("aroma"));
        if (!hasSaunaLeft) {
          localStorage.removeItem("hasBookedSauna");
        }
        switchStage(currentStage, currentSeason);
      });
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }

  const fiscalSummary = computeFiscalSummary(cart.getItems());
  const fiscalContainer = document.getElementById("fiscalItemsSummary");
  if (fiscalContainer) {
    fiscalContainer.innerHTML = "";
    if (fiscalSummary.length === 0) {
      fiscalContainer.innerHTML = `<em style="font-size: 11px; color: var(--text-muted);">Позиции не выбраны</em>`;
    } else {
      fiscalSummary.forEach(f => {
        const div = document.createElement("div");
        div.style.cssText = "font-size: 11px; color: #34d399;";
        div.innerHTML = `• <strong>${f.fiscalName}</strong>: ${f.totalPrice.toLocaleString("ru-RU")} ₽`;
        fiscalContainer.appendChild(div);
      });
    }
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  renderFullCatalogue("all");
  renderFiscalDebugTable();

  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // Quick Order Add Buttons (.btn-quick-add) for Sauna Carousel & Grid
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      let item = CATALOG_ITEMS.find(i => i.id === id);
      if (id === "late-checkout-16") item = LATE_CHECKOUT_ITEM;
      if (id === "coffee-croissant") {
        item = { id: "coffee-croissant", displayName: "☕ Свежий кофе и круассаны в домик", price: 550, category: "service", fiscalName: "Услуги организации питания в номере" };
      }
      if (item) {
        if (item.category === "sauna" || id.includes("sauna") || id.includes("hottub") || id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
        switchStage(currentStage, currentSeason);
      }
    });
  });

  // Edit booked sauna button (unhides sauna section)
  const editSaunaBtn = document.getElementById("showSaunaCarouselBtn");
  if (editSaunaBtn) {
    editSaunaBtn.addEventListener("click", () => {
      const saunaBookedBanner = document.getElementById("saunaBookedBanner");
      const saunaSection = document.getElementById("saunaSection");
      if (saunaBookedBanner) saunaBookedBanner.classList.add("hidden");
      if (saunaSection) {
        saunaSection.classList.remove("hidden");
        saunaSection.scrollIntoView({ behavior: "smooth" });
      }
    });
  }

  // Toggle Demo Menu Panel
  const toggleDemoBtn = document.getElementById("toggleDemoMenuBtn");
  const demoPanel = document.getElementById("demoMenuPanel");
  if (toggleDemoBtn && demoPanel) {
    toggleDemoBtn.addEventListener("click", () => {
      demoPanel.classList.toggle("hidden");
    });
  }

  // Stage & Season Selector with Full Page Reload & Persistence
  const stageSelector = document.getElementById("stageSelector");
  const seasonSelector = document.getElementById("seasonSelector");

  // Read from URL parameters or localStorage, defaulting to Stage 1!
  const urlParams = new URLSearchParams(window.location.search);
  const savedStage = urlParams.get("stage") || localStorage.getItem("demoStage") || "1";
  const savedSeason = urlParams.get("season") || localStorage.getItem("demoSeason") || "summer";

  currentStage = savedStage;
  currentSeason = savedSeason;

  if (stageSelector) stageSelector.value = currentStage;
  if (seasonSelector) seasonSelector.value = currentSeason;

  // Apply initial stage view
  switchStage(currentStage, currentSeason, (bannerConfig) => {
    if (bannerConfig.actionCategory) {
      const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
      if (catBtn) catBtn.click();
      const catalogEl = document.getElementById("fullCatalogueList");
      if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
    } else if (bannerConfig.actionModal) {
      openModal(bannerConfig.actionModal);
    } else if (bannerConfig.actionItem === "late-checkout-16") {
      cart.addItem(LATE_CHECKOUT_ITEM);
      openDrawer("cartDrawer");
      showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
    }
  });

  const handleStageChange = () => {
    if (!stageSelector || !seasonSelector) return;
    const newStage = stageSelector.value;
    const newSeason = seasonSelector.value;
    localStorage.setItem("demoStage", newStage);
    localStorage.setItem("demoSeason", newSeason);

    // Clean reload to simulate authentic client arrival from the very top!
    window.location.search = `?stage=${newStage}&season=${newSeason}`;
  };

  if (stageSelector && seasonSelector) {
    stageSelector.addEventListener("change", handleStageChange);
    seasonSelector.addEventListener("change", handleStageChange);
  }

  // Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(0)";
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(100%)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 250);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(1)";
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(0.95)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 200);
  };

  // Header Cart Button
  const openCartHeaderBtn = document.getElementById("openCartHeaderBtn");
  const closeCartBtn = document.getElementById("closeCartBtn");
  if (openCartHeaderBtn) openCartHeaderBtn.addEventListener("click", () => openDrawer("cartDrawer"));
  if (closeCartBtn) closeCartBtn.addEventListener("click", () => closeDrawer("cartDrawer"));

  // Guide Modal & Registration Modal Close Buttons
  const closeGuideBtn = document.getElementById("closeGuideBtn");
  if (closeGuideBtn) closeGuideBtn.addEventListener("click", () => closeModal("guideModal"));

  const closeRegBtn = document.getElementById("closeRegBtn");
  if (closeRegBtn) closeRegBtn.addEventListener("click", () => closeModal("regModal"));

  const closeOrmBtn = document.getElementById("closeOrmBtn");
  if (closeOrmBtn) closeOrmBtn.addEventListener("click", () => closeModal("ormModal"));

  // Fiscal Debug Drawer Toggle
  const toggleFiscalBtn = document.getElementById("toggleFiscalDebugBtn");
  const closeFiscalBtn = document.getElementById("closeFiscalDebugBtn");
  if (toggleFiscalBtn) toggleFiscalBtn.addEventListener("click", () => {
    if (demoPanel) demoPanel.classList.add("hidden");
    openDrawer("fiscalDebugDrawer");
  });
  if (closeFiscalBtn) closeFiscalBtn.addEventListener("click", () => closeDrawer("fiscalDebugDrawer"));

  // Online Registration Form Submission
  const submitRegBtn = document.getElementById("submitRegBtn");
  if (submitRegBtn) {
    submitRegBtn.addEventListener("click", () => {
      const phone = document.getElementById("regPhone")?.value;
      if (!phone || phone.trim() === "") {
        showToast("Укажите ваш контактный телефон для связи", "⚠️ Внимание");
        return;
      }
      showToast("✅ Онлайн-регистрация завершена, Ирина! Пропуск на въезд для вашего автомобиля оформлен.", "📋 Добро пожаловать");
      closeModal("regModal");
    });
  }

  // Wi-Fi Copy Button (Password: 11111111)
  const copyWifiBtn = document.getElementById("copyWifiBtn");
  if (copyWifiBtn) {
    copyWifiBtn.addEventListener("click", () => {
      navigator.clipboard.writeText("11111111");
      showToast("Пароль 11111111 скопирован в буфер обмена", "📡 Wi-Fi подключение");
    });
  }

  // Housekeeping Rating Stars (Stage 2)
  const hkStars = document.querySelectorAll(".hk-star");
  const hkFeedbackBox = document.getElementById("hkFeedbackBox");
  const submitHkBtn = document.getElementById("submitHkBtn");

  hkStars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      hkStars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });
      if (rating >= 4) {
        if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
        triggerConfetti();
        showToast("🎉 Спасибо за высокую оценку чистоты! Передали благодарность нашей горничной Ладога Парк.", "✨ Отличная уборка");
      } else {
        if (hkFeedbackBox) hkFeedbackBox.classList.remove("hidden");
      }
    });
  });

  if (submitHkBtn) {
    submitHkBtn.addEventListener("click", () => {
      const text = document.getElementById("hkText")?.value;
      if (!text || text.trim() === "") {
        showToast("Напишите, что нам исправить в номере", "⚠️ Внимание");
        return;
      }
      showToast("Ваше замечание по уборке отправлено лично управляющему. Сейчас всё исправим!", "🙏 Спасибо за сигнал");
      if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
    });
  }

  // ORM Interactive Rating Stars (Stage 4)
  const stars = document.querySelectorAll(".star-btn");
  const lowForm = document.getElementById("lowRatingForm");
  const highCard = document.getElementById("highRatingCard");

  stars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      stars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });

      if (rating >= 4) {
        if (lowForm) lowForm.classList.add("hidden");
        if (highCard) {
          highCard.classList.remove("hidden");
          highCard.classList.add("animate-fade-in");
        }
        triggerConfetti();
        showToast("Спасибо за вашу высокую оценку!", "🎉 Ладога Парк");
      } else {
        if (highCard) highCard.classList.add("hidden");
        if (lowForm) {
          lowForm.classList.remove("hidden");
          lowForm.classList.add("animate-fade-in");
        }
      }
    });
  });

  // Submit Feedback Button
  const submitFeedbackBtn = document.getElementById("submitFeedbackBtn");
  if (submitFeedbackBtn) {
    submitFeedbackBtn.addEventListener("click", () => {
      const text = document.getElementById("feedbackText")?.value;
      if (!text || text.trim() === "") {
        showToast("Пожалуйста, напишите пару слов о вашем впечатлении", "⚠️ Внимание");
        return;
      }
      showToast("Отзыв отправлен лично управляющему парком. Мы свяжемся с вами!", "🙏 Спасибо за помощь");
      closeModal("ormModal");
    });
  }

  // Order Submission
  const submitOrderBtn = document.getElementById("submitOrderBtn");
  if (submitOrderBtn) {
    submitOrderBtn.addEventListener("click", () => {
      if (cart.getItems().length === 0) {
        showToast("Сначала добавьте услуги в корзину", "🛒 Корзина пуста");
        return;
      }
      const payType = document.querySelector('input[name="payType"]:checked')?.value;
      const total = cart.getTotalPrice();
      if (payType === "sbp") {
        showToast(`Инициирована оплата СБП на сумму ${total.toLocaleString("ru-RU")} ₽. Электронный чек ОФД сформирован.`, "⚡ Оплата СБП");
      } else {
        showToast(`Заказ на сумму ${total.toLocaleString("ru-RU")} ₽ добавлен в ваш фолио TravelLine. Оплата при выезде.`, "🏨 Фолио обновлено");
      }
      cart.clearCart();
      closeDrawer("cartDrawer");
    });
  }

  // Support FAB Button
  const fabSupportBtn = document.getElementById("fabSupportBtn");
  if (fabSupportBtn) {
    fabSupportBtn.addEventListener("click", () => {
      showToast("Связь с консьерж-сервисом Ладога Парк: +7 (812) 555-01-26 (Круглосуточно)", "📞 Консьерж на связи");
    });
  }

  // Call Admin Button inside Guide Modal
  const callAdminBtn = document.getElementById("callAdminBtn");
  if (callAdminBtn) {
    callAdminBtn.addEventListener("click", () => {
      showToast("Набираем номер службы размещения...", "📞 Администратор");
    });
  }
});

import { triggerConfetti } from "./confetti.js";
import { CATALOG_ITEMS, LATE_CHECKOUT_ITEM } from "./catalogData.js";
import { cart } from "./cartManager.js";
import { switchStage } from "./stageManager.js";
import { computeFiscalSummary } from "./fiscalMapper.js";

let currentCategory = "all";
let currentStage = "1";
let currentSeason = "summer";

// Toast Notification Helper (Clean Emojis - No ligatures!)
function showToast(message, title = "🔔 Уведомление") {
  const container = document.getElementById("toastContainer");
  if (!container) return;
  const toast = document.createElement("div");
  toast.className = "glass-card p-3 animate-float-in pointer-events-auto";
  toast.style.cssText = "background: rgba(20,31,25,0.95); border: 1px solid rgba(232,165,88,0.5); color: #f3f4f6; border-radius: 1rem; box-shadow: 0 10px 30px rgba(0,0,0,0.8); font-size: 0.75rem; display: flex; align-items: flex-start; gap: 0.625rem; padding: 0.875rem;";
  toast.innerHTML = `
    <span style="font-size: 20px; margin-top: 2px;">✨</span>
    <div>
      <strong style="color: var(--accent-gold); font-weight: 700; display: block; margin-bottom: 0.125rem;">${title}</strong>
      <p style="color: var(--text-muted); line-height: 1.4;">${message}</p>
    </div>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(-10px)";
    toast.style.transition = "all 0.3s ease";
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// Render Full Catalogue Items List
function renderFullCatalogue(category = "all") {
  const listContainer = document.getElementById("fullCatalogueList");
  if (!listContainer) return;
  listContainer.innerHTML = "";

  const filtered = category === "all" 
    ? CATALOG_ITEMS 
    : CATALOG_ITEMS.filter(i => i.category === category);

  filtered.forEach(product => {
    const card = document.createElement("div");
    card.className = "glass-card p-4";
    card.style.cssText = "padding: 1rem; border-radius: 1.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem;";
    card.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.875rem;">
        <div style="width: 3rem; height: 3rem; border-radius: 1rem; background: rgba(232,165,88,0.1); border: 1px solid rgba(232,165,88,0.2); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0;">
          ${product.icon}
        </div>
        <div>
          <h4 style="font-weight: 700; font-size: 0.875rem; color: #f3f4f6; line-height: 1.3;">${product.displayName}</h4>
          <p style="font-size: 11px; color: var(--text-muted); margin-top: 0.125rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">${product.desc}</p>
        </div>
      </div>
      <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 0.5rem; flex-shrink: 0;">
        <span style="font-size: 0.875rem; font-weight: 800; color: var(--accent-gold); white-space: nowrap;">${product.price.toLocaleString("ru-RU")} ₽</span>
        <button class="btn-add-item btn-primary-gold" style="padding: 0.375rem 0.875rem; font-size: 0.75rem; white-space: nowrap;" data-id="${product.id}">
          + Добавить
        </button>
      </div>
    `;
    listContainer.appendChild(card);
  });

  listContainer.querySelectorAll(".btn-add-item").forEach(btn => {
    btn.addEventListener("click", () => {
      const item = CATALOG_ITEMS.find(i => i.id === btn.dataset.id);
      if (item) {
        if (item.category === "sauna" || item.id.includes("sauna") || item.id.includes("hottub") || item.id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Добавлено в корзину");
        switchStage(currentStage, currentSeason);
      }
    });
  });
}

// Render Fiscal Debug Table
function renderFiscalDebugTable() {
  const tbody = document.getElementById("fiscalTableBody");
  if (!tbody) return;
  tbody.innerHTML = "";

  CATALOG_ITEMS.concat(LATE_CHECKOUT_ITEM).forEach(item => {
    const tr = document.createElement("tr");
    tr.style.cssText = "border-bottom: 1px solid rgba(232,165,88,0.15); font-size: 0.75rem;";
    tr.innerHTML = `
      <td style="padding: 0.625rem 0.5rem 0.625rem 0;">
        <strong style="display: block; color: #f3f4f6; font-family: var(--font-sans);">${item.displayName}</strong>
        <span style="font-size: 10px; color: var(--text-muted);">${item.price} ₽</span>
      </td>
      <td style="padding: 0.625rem 0;">
        <span style="font-weight: 600; color: #34d399; background: rgba(52,211,153,0.15); border: 1px solid rgba(52,211,153,0.3); padding: 0.125rem 0.5rem; border-radius: 0.375rem; font-size: 11px;">${item.fiscalName}</span>
      </td>
    `;
    tbody.appendChild(tr);
  });
}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (headerBadge) {
    if (count > 0) {
      headerBadge.innerText = count;
      headerBadge.classList.remove("hidden");
      headerBadge.style.display = "flex";
    } else {
      headerBadge.classList.add("hidden");
      headerBadge.style.display = "none";
    }
  }

  const finalTotalEl = document.getElementById("drawerFinalTotal");
  if (finalTotalEl) finalTotalEl.innerText = `${total.toLocaleString("ru-RU")} ₽`;

  const itemsList = document.getElementById("cartItemsList");
  if (!itemsList) return;
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 2rem 0;">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "glass-card";
      row.style.cssText = "padding: 0.875rem; border-radius: 1rem; display: flex; align-items: center; justify-content: space-between; border-color: rgba(232,165,88,0.3); gap: 0.5rem;";
      row.innerHTML = `
        <div style="padding-right: 0.5rem; overflow: hidden;">
          <strong style="font-size: 0.75rem; color: #f3f4f6; display: block; line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.displayName}</strong>
          <span style="font-size: 11px; color: var(--accent-gold); font-weight: 700; margin-top: 0.125rem; display: block;">${item.price.toLocaleString("ru-RU")} ₽ / шт.</span>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
          <button class="btn-minus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">-</button>
          <span style="font-size: 0.75rem; font-weight: 800; width: 1rem; text-align: center;">${item.quantity}</span>
          <button class="btn-plus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">+</button>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => {
        cart.removeItem(b.dataset.id);
        const hasSaunaLeft = cart.getItems().some(i => i.category === "sauna" || i.id.includes("sauna") || i.id.includes("hottub") || i.id.includes("aroma"));
        if (!hasSaunaLeft) {
          localStorage.removeItem("hasBookedSauna");
        }
        switchStage(currentStage, currentSeason);
      });
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }

  const fiscalSummary = computeFiscalSummary(cart.getItems());
  const fiscalContainer = document.getElementById("fiscalItemsSummary");
  if (fiscalContainer) {
    fiscalContainer.innerHTML = "";
    if (fiscalSummary.length === 0) {
      fiscalContainer.innerHTML = `<em style="font-size: 11px; color: var(--text-muted);">Позиции не выбраны</em>`;
    } else {
      fiscalSummary.forEach(f => {
        const div = document.createElement("div");
        div.style.cssText = "font-size: 11px; color: #34d399;";
        div.innerHTML = `• <strong>${f.fiscalName}</strong>: ${f.totalPrice.toLocaleString("ru-RU")} ₽`;
        fiscalContainer.appendChild(div);
      });
    }
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  renderFullCatalogue("all");
  renderFiscalDebugTable();

  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // Quick Order Add Buttons (.btn-quick-add) for Sauna Carousel & Grid
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      let item = CATALOG_ITEMS.find(i => i.id === id);
      if (id === "late-checkout-16") item = LATE_CHECKOUT_ITEM;
      if (id === "coffee-croissant") {
        item = { id: "coffee-croissant", displayName: "☕ Свежий кофе и круассаны в домик", price: 550, category: "service", fiscalName: "Услуги организации питания в номере" };
      }
      if (item) {
        if (item.category === "sauna" || id.includes("sauna") || id.includes("hottub") || id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
        switchStage(currentStage, currentSeason);
      }
    });
  });

  // Edit booked sauna button (unhides sauna section)
  const editSaunaBtn = document.getElementById("showSaunaCarouselBtn");
  if (editSaunaBtn) {
    editSaunaBtn.addEventListener("click", () => {
      const saunaBookedBanner = document.getElementById("saunaBookedBanner");
      const saunaSection = document.getElementById("saunaSection");
      if (saunaBookedBanner) saunaBookedBanner.classList.add("hidden");
      if (saunaSection) {
        saunaSection.classList.remove("hidden");
        saunaSection.scrollIntoView({ behavior: "smooth" });
      }
    });
  }

  // Toggle Demo Menu Panel
  const toggleDemoBtn = document.getElementById("toggleDemoMenuBtn");
  const demoPanel = document.getElementById("demoMenuPanel");
  if (toggleDemoBtn && demoPanel) {
    toggleDemoBtn.addEventListener("click", () => {
      demoPanel.classList.toggle("hidden");
    });
  }

  // Stage & Season Selector with Instant SPA Transition (Zero Network Reloads!)
  const stageSelector = document.getElementById("stageSelector");
  const seasonSelector = document.getElementById("seasonSelector");

  // Read from URL parameters or localStorage, defaulting to Stage 1!
  const urlParams = new URLSearchParams(window.location.search);
  const savedStage = urlParams.get("stage") || localStorage.getItem("demoStage") || "1";
  const savedSeason = urlParams.get("season") || localStorage.getItem("demoSeason") || "summer";

  currentStage = savedStage;
  currentSeason = savedSeason;

  if (stageSelector) stageSelector.value = currentStage;
  if (seasonSelector) seasonSelector.value = currentSeason;

  // Apply initial stage view
  switchStage(currentStage, currentSeason, (bannerConfig) => {
    if (bannerConfig.actionCategory) {
      const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
      if (catBtn) catBtn.click();
      const catalogEl = document.getElementById("fullCatalogueList");
      if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
    } else if (bannerConfig.actionModal) {
      openModal(bannerConfig.actionModal);
    } else if (bannerConfig.actionItem === "late-checkout-16") {
      cart.addItem(LATE_CHECKOUT_ITEM);
      openDrawer("cartDrawer");
      showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
    }
  });

  // INSTANT SPA STAGE SWITCHING (0ms latency, zero HTTP re-downloads!)
  const handleStageChange = () => {
    if (!stageSelector || !seasonSelector) return;
    const newStage = stageSelector.value;
    const newSeason = seasonSelector.value;
    localStorage.setItem("demoStage", newStage);
    localStorage.setItem("demoSeason", newSeason);

    currentStage = newStage;
    currentSeason = newSeason;

    // Update URL cleanly without triggering a slow browser network reload
    history.pushState(null, "", `?stage=${newStage}&season=${newSeason}`);

    // Close any open modals and drawers
    const regModal = document.getElementById("regModal");
    const guideModal = document.getElementById("guideModal");
    const ormModal = document.getElementById("ormModal");
    const cartDrawer = document.getElementById("cartDrawer");
    const fiscalDebugDrawer = document.getElementById("fiscalDebugDrawer");

    if (regModal) regModal.classList.add("opacity-0", "pointer-events-none");
    if (guideModal) guideModal.classList.add("opacity-0", "pointer-events-none");
    if (ormModal) ormModal.classList.add("opacity-0", "pointer-events-none");
    if (cartDrawer) {
      const child = cartDrawer.querySelector(".drawer-panel");
      if (child) child.style.transform = "translateX(100%)";
      cartDrawer.classList.add("opacity-0", "pointer-events-none");
    }
    if (fiscalDebugDrawer) {
      const child = fiscalDebugDrawer.querySelector(".drawer-panel");
      if (child) child.style.transform = "translateX(100%)";
      fiscalDebugDrawer.classList.add("opacity-0", "pointer-events-none");
    }

    // Reset tabs to all
    const allTabBtn = document.querySelector('.tab-btn[data-cat="all"]');
    if (allTabBtn) allTabBtn.click();

    // Instant scroll to top
    window.scrollTo({ top: 0, behavior: "instant" });

    // Execute instant stage transition
    switchStage(currentStage, currentSeason, (bannerConfig) => {
      if (bannerConfig.actionCategory) {
        const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
        if (catBtn) catBtn.click();
        const catalogEl = document.getElementById("fullCatalogueList");
        if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
      } else if (bannerConfig.actionModal) {
        const modal = document.getElementById(bannerConfig.actionModal);
        if (modal) {
          modal.classList.remove("opacity-0", "pointer-events-none");
          const child = modal.querySelector(".glass-modal");
          if (child) child.style.transform = "scale(1)";
        }
      } else if (bannerConfig.actionItem === "late-checkout-16") {
        cart.addItem(LATE_CHECKOUT_ITEM);
        const drawer = document.getElementById("cartDrawer");
        if (drawer) {
          drawer.classList.remove("opacity-0", "pointer-events-none");
          const child = drawer.querySelector(".drawer-panel");
          if (child) child.style.transform = "translateX(0)";
        }
        showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
      }
    });

    showToast(`Включен демонстрационный режим: Этап ${newStage}`, "⚙️ Настройки обновлены");
  };

  if (stageSelector && seasonSelector) {
    stageSelector.addEventListener("change", handleStageChange);
    seasonSelector.addEventListener("change", handleStageChange);
  }

  // Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(0)";
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(100%)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 250);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(1)";
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(0.95)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 200);
  };

  // Header Cart Button
  const openCartHeaderBtn = document.getElementById("openCartHeaderBtn");
  const closeCartBtn = document.getElementById("closeCartBtn");
  if (openCartHeaderBtn) openCartHeaderBtn.addEventListener("click", () => openDrawer("cartDrawer"));
  if (closeCartBtn) closeCartBtn.addEventListener("click", () => closeDrawer("cartDrawer"));

  // Guide Modal & Registration Modal Close Buttons
  const closeGuideBtn = document.getElementById("closeGuideBtn");
  if (closeGuideBtn) closeGuideBtn.addEventListener("click", () => closeModal("guideModal"));

  const closeRegBtn = document.getElementById("closeRegBtn");
  if (closeRegBtn) closeRegBtn.addEventListener("click", () => closeModal("regModal"));

  const closeOrmBtn = document.getElementById("closeOrmBtn");
  if (closeOrmBtn) closeOrmBtn.addEventListener("click", () => closeModal("ormModal"));

  // Fiscal Debug Drawer Toggle
  const toggleFiscalBtn = document.getElementById("toggleFiscalDebugBtn");
  const closeFiscalBtn = document.getElementById("closeFiscalDebugBtn");
  if (toggleFiscalBtn) toggleFiscalBtn.addEventListener("click", () => {
    if (demoPanel) demoPanel.classList.add("hidden");
    openDrawer("fiscalDebugDrawer");
  });
  if (closeFiscalBtn) closeFiscalBtn.addEventListener("click", () => closeDrawer("fiscalDebugDrawer"));

  // Online Registration Form Submission
  const submitRegBtn = document.getElementById("submitRegBtn");
  if (submitRegBtn) {
    submitRegBtn.addEventListener("click", () => {
      const phone = document.getElementById("regPhone")?.value;
      if (!phone || phone.trim() === "") {
        showToast("Укажите ваш контактный телефон для связи", "⚠️ Внимание");
        return;
      }
      showToast("✅ Онлайн-регистрация завершена, Ирина! Пропуск на въезд для вашего автомобиля оформлен.", "📋 Добро пожаловать");
      closeModal("regModal");
    });
  }

  // Wi-Fi Copy Button (Password: 11111111)
  const copyWifiBtn = document.getElementById("copyWifiBtn");
  if (copyWifiBtn) {
    copyWifiBtn.addEventListener("click", () => {
      navigator.clipboard.writeText("11111111");
      showToast("Пароль 11111111 скопирован в буфер обмена", "📡 Wi-Fi подключение");
    });
  }

  // Housekeeping Rating Stars (Stage 2)
  const hkStars = document.querySelectorAll(".hk-star");
  const hkFeedbackBox = document.getElementById("hkFeedbackBox");
  const submitHkBtn = document.getElementById("submitHkBtn");

  hkStars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      hkStars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });
      if (rating >= 4) {
        if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
        triggerConfetti();
        showToast("🎉 Спасибо за высокую оценку чистоты! Передали благодарность нашей горничной Ладога Парк.", "✨ Отличная уборка");
      } else {
        if (hkFeedbackBox) hkFeedbackBox.classList.remove("hidden");
      }
    });
  });

  if (submitHkBtn) {
    submitHkBtn.addEventListener("click", () => {
      const text = document.getElementById("hkText")?.value;
      if (!text || text.trim() === "") {
        showToast("Напишите, что нам исправить в номере", "⚠️ Внимание");
        return;
      }
      showToast("Ваше замечание по уборке отправлено лично управляющему. Сейчас всё исправим!", "🙏 Спасибо за сигнал");
      if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
    });
  }

  // ORM Interactive Rating Stars (Stage 4)
  const stars = document.querySelectorAll(".star-btn");
  const lowForm = document.getElementById("lowRatingForm");
  const highCard = document.getElementById("highRatingCard");

  stars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      stars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });

      if (rating >= 4) {
        if (lowForm) lowForm.classList.add("hidden");
        if (highCard) {
          highCard.classList.remove("hidden");
          highCard.classList.add("animate-fade-in");
        }
        triggerConfetti();
        showToast("Спасибо за вашу высокую оценку!", "🎉 Ладога Парк");
      } else {
        if (highCard) highCard.classList.add("hidden");
        if (lowForm) {
          lowForm.classList.remove("hidden");
          lowForm.classList.add("animate-fade-in");
        }
      }
    });
  });

  // Submit Feedback Button
  const submitFeedbackBtn = document.getElementById("submitFeedbackBtn");
  if (submitFeedbackBtn) {
    submitFeedbackBtn.addEventListener("click", () => {
      const text = document.getElementById("feedbackText")?.value;
      if (!text || text.trim() === "") {
        showToast("Пожалуйста, напишите пару слов о вашем впечатлении", "⚠️ Внимание");
        return;
      }
      showToast("Отзыв отправлен лично управляющему парком. Мы свяжемся с вами!", "🙏 Спасибо за помощь");
      closeModal("ormModal");
    });
  }

  // Order Submission
  const submitOrderBtn = document.getElementById("submitOrderBtn");
  if (submitOrderBtn) {
    submitOrderBtn.addEventListener("click", () => {
      if (cart.getItems().length === 0) {
        showToast("Сначала добавьте услуги в корзину", "🛒 Корзина пуста");
        return;
      }
      const payType = document.querySelector('input[name="payType"]:checked')?.value;
      const total = cart.getTotalPrice();
      if (payType === "sbp") {
        showToast(`Инициирована оплата СБП на сумму ${total.toLocaleString("ru-RU")} ₽. Электронный чек ОФД сформирован.`, "⚡ Оплата СБП");
      } else {
        showToast(`Заказ на сумму ${total.toLocaleString("ru-RU")} ₽ добавлен в ваш фолио TravelLine. Оплата при выезде.`, "🏨 Фолио обновлено");
      }
      cart.clearCart();
      closeDrawer("cartDrawer");
    });
  }

  // Support FAB Button
  const fabSupportBtn = document.getElementById("fabSupportBtn");
  if (fabSupportBtn) {
    fabSupportBtn.addEventListener("click", () => {
      showToast("Связь с консьерж-сервисом Ладога Парк: +7 (812) 555-01-26 (Круглосуточно)", "📞 Консьерж на связи");
    });
  }

  // Call Admin Button inside Guide Modal
  const callAdminBtn = document.getElementById("callAdminBtn");
  if (callAdminBtn) {
    callAdminBtn.addEventListener("click", () => {
      showToast("Набираем номер службы размещения...", "📞 Администратор");
    });
  }
});

/*
 * Ладога Парк | Эко-курорт PWA ("Живой домик")
 * Pure CSS Design System & Hardware Accelerated Animations (Zero CDN dependency!)
 */

:root {
  --bg-dark: #0b110e;
  --bg-card: rgba(18, 28, 23, 0.75);
  --bg-pine: #121c17;
  --bg-pine-light: #1a2820;
  --primary-ember: #e8a558;
  --accent-gold: #f3bc7a;
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --border-ember: rgba(232, 165, 88, 0.25);
  --font-sans: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Cormorant Garamond', Georgia, serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-sans);
  overflow-x: hidden;
  line-height: 1.5;
}

/* 100svh prevents mobile address bar layout jumps */
.hero-container {
  position: relative;
  width: 100vw;
  height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 5rem 1.25rem 2rem;
  overflow: hidden;
}

.video-background-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: hidden;
  background-color: #050806;
}

/* Clean, Full-Frame Video Rendering (NO ZOOM BUG, NO DOUBLE SCALING!) */
.hero-video {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0;
  transition: opacity 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: opacity;
  pointer-events: none;
}

.hero-video.active {
  opacity: 1;
}

.vignette-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(to bottom, rgba(11,17,14,0.55) 0%, rgba(11,17,14,0.1) 30%, rgba(11,17,14,0.35) 75%, rgba(11,17,14,0.95) 100%),
    radial-gradient(circle at center, transparent 40%, rgba(5,8,6,0.55) 100%);
  pointer-events: none;
}

/* Smooth, Gentle Luxury Appearance (1.2s delay, 1.2s smooth fade - 100% buttery!) */
.fade-in-delayed {
  opacity: 0;
  animation: fadeInSmooth 1.2s cubic-bezier(0.25, 0.1, 0.25, 1) 1.2s forwards;
  will-change: opacity, transform;
}

@keyframes fadeInSmooth {
  0% {
    opacity: 0;
    transform: translateY(14px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Glassmorphism Cards */
.glass-card {
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-ember);
  border-radius: 1.25rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.glass-card:hover {
  border-color: rgba(232, 165, 88, 0.45);
}

/* Buttons with NO WRAP guarantee for prices! */
.btn-primary-gold {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-family: var(--font-sans);
  font-weight: 800;
  border: none;
  border-radius: 9999px;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(232, 165, 88, 0.35);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-primary-gold:active {
  transform: scale(0.97);
  box-shadow: 0 2px 10px rgba(232, 165, 88, 0.25);
}

.btn-icon-round {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid var(--border-ember);
  background: rgba(232, 165, 88, 0.15);
  color: var(--accent-gold);
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.btn-icon-round:active {
  transform: scale(0.9);
  background: rgba(232, 165, 88, 0.3);
}

/* Clickable Taxi Phone Button */
.btn-taxi {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: #14221c;
  border: 1px solid rgba(96, 165, 250, 0.3);
  border-radius: 1rem;
  color: #60a5fa;
  text-decoration: none;
  font-size: 0.75rem;
  font-weight: 600;
  transition: all 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-taxi:active {
  background: rgba(96, 165, 250, 0.15);
  transform: scale(0.98);
}

/* Category Tabs */
.tab-btn {
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--bg-pine);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.tab-btn.active {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-weight: 800;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(232, 165, 88, 0.3);
}

/* Modals and Drawers */
.modal-overlay,
.drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100svh;
  background: rgba(5, 8, 6, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.25s ease;
  padding: 1rem;
}

.glass-modal {
  background: #121c17;
  border: 1px solid var(--border-ember);
  border-radius: 1.5rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8);
  max-height: 90svh;
  overflow-y: auto;
}

.drawer-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 100%;
  max-width: 24rem;
  height: 100%;
  background: #121c17;
  border-left: 1px solid var(--border-ember);
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Utilities */
.hidden { display: none !important; }
.opacity-0 { opacity: 0 !important; }
.pointer-events-none { pointer-events: none !important; }
.pointer-events-auto { pointer-events: auto !important; }

@keyframes bounceSlow {
  0%, 100% { transform: translateY(-25%); animation-timing-function: cubic-bezier(0.8,0,1,1); }
  50% { transform: none; animation-timing-function: cubic-bezier(0,0,0.2,1); }
}
.animate-bounce { animation: bounceSlow 2s infinite; }

@keyframes floatIn {
  0% { opacity: 0; transform: translateY(-10px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.animate-float-in { animation: floatIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards; }

/**
 * Stage & Season Manager ("Живой домик" Mobile Atmospheric UX)
 * Contextual stage filtering: Stage 4 has ZERO menu/sauna, Stage 3 shows morning service, Stage 2 shows sightseeing/housekeeping, Stage 1 shows sauna swipable carousel
 */

import { cart } from "./cartManager.js";

export const STAGE_CONFIGS = {
  1: {
    stageName: "1. T-1 день до заезда (Предвкушение)",
    videoPath: "/assets/video/stage1.mp4",
    title: "Ирина, ждём вас завтра!",
    subtitle: "Ваш «Домик рыбака» на берегу озера готовится к приёму. Пройдите онлайн-регистрацию заранее, чтобы получить пропуск на территорию.",
    banner: {
      actionText: "📋 Пройти онлайн-регистрацию",
      actionModal: "regModal"
    }
  },
  2: {
    stageName: "2. В день заезда & Проживание (Обжитой уют)",
    videoPath: "/assets/video/stage2.mp4",
    title: "Добро пожаловать, Ирина!",
    subtitle: "Ваш «Домик рыбака» наполнен теплом. Уютный мангал разжжен и ждёт вашего вечера у огня.",
    banner: {
      actionText: "📜 5 правил проживания, Wi-Fi & Гид",
      actionModal: "guideModal"
    }
  },
  3: {
    stageName: "3. Утро выезда 09:00 (Остывающий очаг)",
    videoPath: "/assets/video/stage3.mp4",
    title: "Ирина, доброе утро!",
    subtitle: "Ваш «Домик рыбака» свободен до вечера! Вы можете продлить проживание до 16:00 и провести день без спешки и суеты.",
    banner: {
      actionText: "⏳ Продлить домик до 16:00 (2 500 ₽)",
      actionItem: "late-checkout-16"
    }
  },
  4: {
    stageName: "4. После выезда +2h (ORM & Прощание)",
    videoPath: "/assets/video/stage4.mp4",
    title: "Ирина, спасибо за отдых!",
    subtitle: "Мы уже скучаем по вам в «Домике рыбака»! Оцените ваше пребывание и заберите персональный подарок на следующий сезон.",
    banner: {
      actionText: "🌟 Оценить отдых & Забрать подарок",
      actionModal: "ormModal"
    }
  }
};

let activeVideoIndex = 1;

export function switchStage(stageId, season = "summer", onActionClick) {
  const config = STAGE_CONFIGS[stageId];
  if (!config) return;

  // 1. Silky Smooth Cross-fade video logic (Zero Dual-Decoding / Freezing on load!)
  const video1 = document.getElementById("heroVideo1");
  const video2 = document.getElementById("heroVideo2");

  if (video1 && video2) {
    const currentActive = activeVideoIndex === 1 ? video1 : video2;
    const currentInactive = activeVideoIndex === 1 ? video2 : video1;

    // Avoid dual decoding or reloading if the current active video is already playing this exact source!
    const activeSrc = currentActive.getAttribute("src") || "";
    if (activeSrc === config.videoPath || (currentActive.src && currentActive.src.endsWith(config.videoPath))) {
      // The video is already loaded and playing smoothly on currentActive! Do not touch decoders!
    } else {
      currentInactive.src = config.videoPath;
      currentInactive.load();

      const playPromise = currentInactive.play();
      if (playPromise !== undefined) {
        playPromise.then(() => {
          currentInactive.classList.add("active");
          currentActive.classList.remove("active");
          activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
        }).catch(e => {
          console.log("Auto-play prevented or loading:", e);
          currentInactive.classList.add("active");
          currentActive.classList.remove("active");
          activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
        });
      } else {
        currentInactive.classList.add("active");
        currentActive.classList.remove("active");
        activeVideoIndex = activeVideoIndex === 1 ? 2 : 1;
      }
    }
  }

  // 2. Update Atmospheric Texts smoothly
  const titleEl = document.getElementById("heroTitle");
  const subtitleEl = document.getElementById("heroSubtitle");

  if (titleEl) titleEl.innerText = config.title;
  if (subtitleEl) subtitleEl.innerText = config.subtitle;

  // 3. Render Floating Luxury Action Button (Structure guarantees text & price never wrap!)
  const bannerContainer = document.getElementById("triggerBannerContainer");
  if (bannerContainer) {
    bannerContainer.innerHTML = `
      <button id="triggerActionBtn" class="btn-primary-gold" style="width: 100%; max-width: 20rem; margin: 0 auto; padding: 0.875rem 1.25rem; justify-content: center;">
        <span style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${config.banner.actionText}</span>
      </button>
    `;

    const actionBtn = document.getElementById("triggerActionBtn");
    if (actionBtn) {
      actionBtn.addEventListener("click", () => {
        if (onActionClick) {
          onActionClick(config.banner);
        }
      });
    }
  }

  // 4. CONTEXTUAL STAGE CONTENT FILTERING
  const saunaSection = document.getElementById("saunaSection");
  const saunaBookedBanner = document.getElementById("saunaBookedBanner");
  const stage2GuideSection = document.getElementById("stage2GuideSection");
  const quickOrdersSection = document.getElementById("quickOrdersSection");
  const catalogueSection = document.getElementById("catalogueSection");
  const morningServiceSection = document.getElementById("morningServiceSection");
  const farewellSection = document.getElementById("farewellSection");
  const saunaSectionHeader = document.getElementById("saunaSectionHeader");
  const scrollIndicator = document.getElementById("scrollIndicator");

  // Check if sauna is already booked in cart or localStorage
  const hasBookedSauna = localStorage.getItem("hasBookedSauna") === "true" || 
    cart.getItems().some(i => i.category === "sauna" || i.id.includes("sauna") || i.id.includes("hottub") || i.id.includes("aroma"));

  // Reset all
  if (saunaSection) saunaSection.classList.add("hidden");
  if (saunaBookedBanner) saunaBookedBanner.classList.add("hidden");
  if (stage2GuideSection) stage2GuideSection.classList.add("hidden");
  if (quickOrdersSection) quickOrdersSection.classList.add("hidden");
  if (catalogueSection) catalogueSection.classList.add("hidden");
  if (morningServiceSection) morningServiceSection.classList.add("hidden");
  if (farewellSection) farewellSection.classList.add("hidden");
  if (scrollIndicator) scrollIndicator.style.display = "flex";

  if (stageId === "1" || stageId == 1) {
    // Stage 1: Pre-arrival -> Show Sauna swipable carousel for check-in, Quick Orders, Catalogue
    if (hasBookedSauna) {
      if (saunaBookedBanner) saunaBookedBanner.classList.remove("hidden");
    } else {
      if (saunaSection) saunaSection.classList.remove("hidden");
    }
    if (quickOrdersSection) quickOrdersSection.classList.remove("hidden");
    if (catalogueSection) catalogueSection.classList.remove("hidden");
    if (saunaSectionHeader) saunaSectionHeader.innerText = "Выберите баню к приезду (Свайп ➔)";
  } 
  else if (stageId === "2" || stageId == 2) {
    // Stage 2: In-Stay -> Show Sightseeing Guide, Housekeeping rating, and do NOT duplicate sauna if booked!
    if (stage2GuideSection) stage2GuideSection.classList.remove("hidden");
    if (hasBookedSauna) {
      if (saunaBookedBanner) saunaBookedBanner.classList.remove("hidden");
    } else {
      if (saunaSection) saunaSection.classList.remove("hidden");
    }
    if (quickOrdersSection) quickOrdersSection.classList.remove("hidden");
    if (catalogueSection) catalogueSection.classList.remove("hidden");
    if (saunaSectionHeader) saunaSectionHeader.innerText = "Вечерняя растопка бани (Свайп ➔)";
  } 
  else if (stageId === "3" || stageId == 3) {
    // Stage 3: Morning Departure 09:00 -> NO sauna, NO quick orders! Only morning coffee, late checkout, and taxi!
    if (morningServiceSection) morningServiceSection.classList.remove("hidden");
  } 
  else if (stageId === "4" || stageId == 4) {
    // Stage 4: After Departure -> ZERO MENU, ZERO SAUNA! Pure clean farewell card!
    if (farewellSection) farewellSection.classList.remove("hidden");
    if (scrollIndicator) scrollIndicator.style.display = "none";
  }
}

import { triggerConfetti } from "./confetti.js";
import { CATALOG_ITEMS, LATE_CHECKOUT_ITEM } from "./catalogData.js";
import { cart } from "./cartManager.js";
import { switchStage } from "./stageManager.js";
import { computeFiscalSummary } from "./fiscalMapper.js";

let currentCategory = "all";
let currentStage = "1";
let currentSeason = "summer";

// Toast Notification Helper (Clean Emojis - No ligatures!)
function showToast(message, title = "🔔 Уведомление") {
  const container = document.getElementById("toastContainer");
  if (!container) return;
  const toast = document.createElement("div");
  toast.className = "glass-card p-3 animate-float-in pointer-events-auto";
  toast.style.cssText = "background: rgba(20,31,25,0.95); border: 1px solid rgba(232,165,88,0.5); color: #f3f4f6; border-radius: 1rem; box-shadow: 0 10px 30px rgba(0,0,0,0.8); font-size: 0.75rem; display: flex; align-items: flex-start; gap: 0.625rem; padding: 0.875rem;";
  toast.innerHTML = `
    <span style="font-size: 20px; margin-top: 2px;">✨</span>
    <div>
      <strong style="color: var(--accent-gold); font-weight: 700; display: block; margin-bottom: 0.125rem;">${title}</strong>
      <p style="color: var(--text-muted); line-height: 1.4;">${message}</p>
    </div>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(-10px)";
    toast.style.transition = "all 0.3s ease";
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// Render Full Catalogue Items List
function renderFullCatalogue(category = "all") {
  const listContainer = document.getElementById("fullCatalogueList");
  if (!listContainer) return;
  listContainer.innerHTML = "";

  const filtered = category === "all" 
    ? CATALOG_ITEMS 
    : CATALOG_ITEMS.filter(i => i.category === category);

  filtered.forEach(product => {
    const card = document.createElement("div");
    card.className = "glass-card p-4";
    card.style.cssText = "padding: 1rem; border-radius: 1.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem;";
    card.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.875rem;">
        <div style="width: 3rem; height: 3rem; border-radius: 1rem; background: rgba(232,165,88,0.1); border: 1px solid rgba(232,165,88,0.2); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0;">
          ${product.icon}
        </div>
        <div>
          <h4 style="font-weight: 700; font-size: 0.875rem; color: #f3f4f6; line-height: 1.3;">${product.displayName}</h4>
          <p style="font-size: 11px; color: var(--text-muted); margin-top: 0.125rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">${product.desc}</p>
        </div>
      </div>
      <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 0.5rem; flex-shrink: 0;">
        <span style="font-size: 0.875rem; font-weight: 800; color: var(--accent-gold); white-space: nowrap;">${product.price.toLocaleString("ru-RU")} ₽</span>
        <button class="btn-add-item btn-primary-gold" style="padding: 0.375rem 0.875rem; font-size: 0.75rem; white-space: nowrap;" data-id="${product.id}">
          + Добавить
        </button>
      </div>
    `;
    listContainer.appendChild(card);
  });

  listContainer.querySelectorAll(".btn-add-item").forEach(btn => {
    btn.addEventListener("click", () => {
      const item = CATALOG_ITEMS.find(i => i.id === btn.dataset.id);
      if (item) {
        if (item.category === "sauna" || item.id.includes("sauna") || item.id.includes("hottub") || item.id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Добавлено в корзину");
        switchStage(currentStage, currentSeason);
      }
    });
  });
}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (headerBadge) {
    if (count > 0) {
      headerBadge.innerText = count;
      headerBadge.classList.remove("hidden");
      headerBadge.style.display = "flex";
    } else {
      headerBadge.classList.add("hidden");
      headerBadge.style.display = "none";
    }
  }

  const finalTotalEl = document.getElementById("drawerFinalTotal");
  if (finalTotalEl) finalTotalEl.innerText = `${total.toLocaleString("ru-RU")} ₽`;

  const itemsList = document.getElementById("cartItemsList");
  if (!itemsList) return;
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 2rem 0;">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "glass-card";
      row.style.cssText = "padding: 0.875rem; border-radius: 1rem; display: flex; align-items: center; justify-content: space-between; border-color: rgba(232,165,88,0.3); gap: 0.5rem;";
      row.innerHTML = `
        <div style="padding-right: 0.5rem; overflow: hidden;">
          <strong style="font-size: 0.75rem; color: #f3f4f6; display: block; line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.displayName}</strong>
          <span style="font-size: 11px; color: var(--accent-gold); font-weight: 700; margin-top: 0.125rem; display: block;">${item.price.toLocaleString("ru-RU")} ₽ / шт.</span>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
          <button class="btn-minus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">-</button>
          <span style="font-size: 0.75rem; font-weight: 800; width: 1rem; text-align: center;">${item.quantity}</span>
          <button class="btn-plus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">+</button>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => {
        cart.removeItem(b.dataset.id);
        const hasSaunaLeft = cart.getItems().some(i => i.category === "sauna" || i.id.includes("sauna") || i.id.includes("hottub") || i.id.includes("aroma"));
        if (!hasSaunaLeft) {
          localStorage.removeItem("hasBookedSauna");
        }
        switchStage(currentStage, currentSeason);
      });
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  renderFullCatalogue("all");

  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // Quick Order Add Buttons (.btn-quick-add) for Sauna Carousel & Grid
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      let item = CATALOG_ITEMS.find(i => i.id === id);
      if (id === "late-checkout-16") item = LATE_CHECKOUT_ITEM;
      if (id === "coffee-croissant") {
        item = { id: "coffee-croissant", displayName: "☕ Свежий кофе и круассаны в домик", price: 550, category: "service", fiscalName: "Услуги организации питания в номере" };
      }
      if (item) {
        if (item.category === "sauna" || id.includes("sauna") || id.includes("hottub") || id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
        switchStage(currentStage, currentSeason);
      }
    });
  });

  // Edit booked sauna button (unhides sauna section)
  const editSaunaBtn = document.getElementById("showSaunaCarouselBtn");
  if (editSaunaBtn) {
    editSaunaBtn.addEventListener("click", () => {
      const saunaBookedBanner = document.getElementById("saunaBookedBanner");
      const saunaSection = document.getElementById("saunaSection");
      if (saunaBookedBanner) saunaBookedBanner.classList.add("hidden");
      if (saunaSection) {
        saunaSection.classList.remove("hidden");
        saunaSection.scrollIntoView({ behavior: "smooth" });
      }
    });
  }

  // Toggle Demo Menu Panel
  const toggleDemoBtn = document.getElementById("toggleDemoMenuBtn");
  const demoPanel = document.getElementById("demoMenuPanel");
  if (toggleDemoBtn && demoPanel) {
    toggleDemoBtn.addEventListener("click", () => {
      demoPanel.classList.toggle("hidden");
    });
  }

  // Stage Selector with Instant SPA Transition (Zero Network Reloads!)
  const stageSelector = document.getElementById("stageSelector");

  // Read from URL parameters or localStorage, defaulting to Stage 1!
  const urlParams = new URLSearchParams(window.location.search);
  const savedStage = urlParams.get("stage") || localStorage.getItem("demoStage") || "1";

  currentStage = savedStage;
  if (stageSelector) stageSelector.value = currentStage;

  // Apply initial stage view
  switchStage(currentStage, currentSeason, (bannerConfig) => {
    if (bannerConfig.actionCategory) {
      const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
      if (catBtn) catBtn.click();
      const catalogEl = document.getElementById("fullCatalogueList");
      if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
    } else if (bannerConfig.actionModal) {
      openModal(bannerConfig.actionModal);
    } else if (bannerConfig.actionItem === "late-checkout-16") {
      cart.addItem(LATE_CHECKOUT_ITEM);
      openDrawer("cartDrawer");
      showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
    }
  });

  // INSTANT SPA STAGE SWITCHING (0ms latency, zero HTTP re-downloads!)
  const handleStageChange = () => {
    if (!stageSelector) return;
    const newStage = stageSelector.value;
    localStorage.setItem("demoStage", newStage);

    currentStage = newStage;

    // Update URL cleanly without triggering a slow browser network reload
    history.pushState(null, "", `?stage=${newStage}`);

    // Close any open modals and drawers
    ["regModal", "guideModal", "ormModal"].forEach(closeModal);
    ["cartDrawer"].forEach(closeDrawer);

    // Reset tabs to all
    const allTabBtn = document.querySelector('.tab-btn[data-cat="all"]');
    if (allTabBtn) allTabBtn.click();

    // Instant scroll to top
    window.scrollTo({ top: 0, behavior: "instant" });

    // Execute instant stage transition
    switchStage(currentStage, currentSeason, (bannerConfig) => {
      if (bannerConfig.actionCategory) {
        const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
        if (catBtn) catBtn.click();
        const catalogEl = document.getElementById("fullCatalogueList");
        if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
      } else if (bannerConfig.actionModal) {
        openModal(bannerConfig.actionModal);
      } else if (bannerConfig.actionItem === "late-checkout-16") {
        cart.addItem(LATE_CHECKOUT_ITEM);
        openDrawer("cartDrawer");
        showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
      }
    });

    showToast(`Включен демонстрационный режим: Этап ${newStage}`, "⚙️ Настройки обновлены");
  };

  if (stageSelector) {
    stageSelector.addEventListener("change", handleStageChange);
  }

  // Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(0)";
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(100%)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 250);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(1)";
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(0.95)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 200);
  };

  // BACKGROUND TAP-TO-CLOSE FOR ALL MODALS & DRAWERS (FOOLPROOF INTUITIVE UX!)
  document.querySelectorAll(".modal-overlay, .drawer-overlay").forEach(overlay => {
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) {
        const id = overlay.id;
        if (overlay.classList.contains("modal-overlay")) {
          closeModal(id);
        } else {
          closeDrawer(id);
        }
      }
    });
  });

  // EXPLICIT BOTTOM CLOSE BUTTONS INSIDE MODALS
  document.querySelectorAll(".btn-close-modal-bottom").forEach(btn => {
    btn.addEventListener("click", () => {
      const modalId = btn.dataset.modal;
      if (modalId) closeModal(modalId);
    });
  });

  // Header Cart Button
  const openCartHeaderBtn = document.getElementById("openCartHeaderBtn");
  const closeCartBtn = document.getElementById("closeCartBtn");
  if (openCartHeaderBtn) openCartHeaderBtn.addEventListener("click", () => openDrawer("cartDrawer"));
  if (closeCartBtn) closeCartBtn.addEventListener("click", () => closeDrawer("cartDrawer"));

  // Top X Close Buttons
  const closeGuideBtn = document.getElementById("closeGuideBtn");
  if (closeGuideBtn) closeGuideBtn.addEventListener("click", () => closeModal("guideModal"));

  const closeRegBtn = document.getElementById("closeRegBtn");
  if (closeRegBtn) closeRegBtn.addEventListener("click", () => closeModal("regModal"));

  const closeOrmBtn = document.getElementById("closeOrmBtn");
  if (closeOrmBtn) closeOrmBtn.addEventListener("click", () => closeModal("ormModal"));

  // Online Registration Form Submission
  const submitRegBtn = document.getElementById("submitRegBtn");
  if (submitRegBtn) {
    submitRegBtn.addEventListener("click", () => {
      const phone = document.getElementById("regPhone")?.value;
      if (!phone || phone.trim() === "") {
        showToast("Укажите ваш контактный телефон для связи", "⚠️ Внимание");
        return;
      }
      showToast("✅ Онлайн-регистрация завершена, Ирина! Пропуск на въезд для вашего автомобиля оформлен.", "📋 Добро пожаловать");
      closeModal("regModal");
    });
  }

  // Wi-Fi Copy Button (Password: 11111111)
  const copyWifiBtn = document.getElementById("copyWifiBtn");
  if (copyWifiBtn) {
    copyWifiBtn.addEventListener("click", () => {
      navigator.clipboard.writeText("11111111");
      showToast("Пароль 11111111 скопирован в буфер обмена", "📡 Wi-Fi подключение");
    });
  }

  // Housekeeping Rating Stars (Stage 2)
  const hkStars = document.querySelectorAll(".hk-star");
  const hkFeedbackBox = document.getElementById("hkFeedbackBox");
  const submitHkBtn = document.getElementById("submitHkBtn");

  hkStars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      hkStars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });
      if (rating >= 4) {
        if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
        triggerConfetti();
        showToast("🎉 Спасибо за высокую оценку чистоты! Передали благодарность нашей горничной Ладога Парк.", "✨ Отличная уборка");
      } else {
        if (hkFeedbackBox) hkFeedbackBox.classList.remove("hidden");
      }
    });
  });

  if (submitHkBtn) {
    submitHkBtn.addEventListener("click", () => {
      const text = document.getElementById("hkText")?.value;
      if (!text || text.trim() === "") {
        showToast("Напишите, что нам исправить в номере", "⚠️ Внимание");
        return;
      }
      showToast("Ваше замечание по уборке отправлено лично управляющему. Сейчас всё исправим!", "🙏 Спасибо за сигнал");
      if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
    });
  }

  // ORM Interactive Rating Stars (Stage 4)
  const stars = document.querySelectorAll(".star-btn");
  const lowForm = document.getElementById("lowRatingForm");
  const highCard = document.getElementById("highRatingCard");

  stars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      stars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });

      if (rating >= 4) {
        if (lowForm) lowForm.classList.add("hidden");
        if (highCard) {
          highCard.classList.remove("hidden");
          highCard.classList.add("animate-fade-in");
        }
        triggerConfetti();
        showToast("Спасибо за вашу высокую оценку!", "🎉 Ладога Парк");
      } else {
        if (highCard) highCard.classList.add("hidden");
        if (lowForm) {
          lowForm.classList.remove("hidden");
          lowForm.classList.add("animate-fade-in");
        }
      }
    });
  });

  // Submit Feedback Button
  const submitFeedbackBtn = document.getElementById("submitFeedbackBtn");
  if (submitFeedbackBtn) {
    submitFeedbackBtn.addEventListener("click", () => {
      const text = document.getElementById("feedbackText")?.value;
      if (!text || text.trim() === "") {
        showToast("Пожалуйста, напишите пару слов о вашем впечатлении", "⚠️ Внимание");
        return;
      }
      showToast("Отзыв отправлен лично управляющему парком. Мы свяжемся с вами!", "🙏 Спасибо за помощь");
      closeModal("ormModal");
    });
  }

  // Order Submission
  const submitOrderBtn = document.getElementById("submitOrderBtn");
  if (submitOrderBtn) {
    submitOrderBtn.addEventListener("click", () => {
      if (cart.getItems().length === 0) {
        showToast("Сначала добавьте услуги в корзину", "🛒 Корзина пуста");
        return;
      }
      const payType = document.querySelector('input[name="payType"]:checked')?.value;
      const total = cart.getTotalPrice();
      if (payType === "sbp") {
        showToast(`Инициирована оплата СБП на сумму ${total.toLocaleString("ru-RU")} ₽. Электронный чек ОФД сформирован.`, "⚡ Оплата СБП");
      } else {
        showToast(`Заказ на сумму ${total.toLocaleString("ru-RU")} ₽ добавлен в ваш фолио TravelLine. Оплата при выезде.`, "🏨 Фолио обновлено");
      }
      cart.clearCart();
      closeDrawer("cartDrawer");
    });
  }

  // Support FAB Button
  const fabSupportBtn = document.getElementById("fabSupportBtn");
  if (fabSupportBtn) {
    fabSupportBtn.addEventListener("click", () => {
      showToast("Связь с консьерж-сервисом Ладога Парк: +7 (812) 555-01-26 (Круглосуточно)", "📞 Консьерж на связи");
    });
  }

  // Call Admin Button inside Guide Modal
  const callAdminBtn = document.getElementById("callAdminBtn");
  if (callAdminBtn) {
    callAdminBtn.addEventListener("click", () => {
      showToast("Набираем номер службы размещения...", "📞 Администратор");
    });
  }
});

/*
 * Ладога Парк | Эко-курорт PWA ("Живой домик")
 * Hardware Accelerated Pure CSS (Smooth Mobile GPU Rendering)
 */

:root {
  --bg-dark: #0b110e;
  --bg-card: rgba(18, 28, 23, 0.85);
  --bg-pine: #121c17;
  --bg-pine-light: #1a2820;
  --primary-ember: #e8a558;
  --accent-gold: #f3bc7a;
  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --border-ember: rgba(232, 165, 88, 0.25);
  --font-sans: 'Outfit', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Cormorant Garamond', Georgia, serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-sans);
  overflow-x: hidden;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Stable Hero Height (Prevents Mobile Address Bar Resize Jumps & Extreme Crop!) */
.hero-container {
  position: relative;
  width: 100%;
  height: 72vh;
  min-height: 480px;
  max-height: 600px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 4.5rem 1.25rem 1.5rem;
  overflow: hidden;
  transform: translateZ(0);
}

.video-background-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: hidden;
  background-color: #050806;
}

/* Object Position Bottom: Brings the WHOLE cabin, lights, ground & lake into view! */
.hero-video {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 85%;
  opacity: 0;
  transition: opacity 1s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: opacity;
  pointer-events: none;
  transform: translateZ(0);
}

.hero-video.active {
  opacity: 1;
}

.vignette-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(to bottom, rgba(11,17,14,0.6) 0%, rgba(11,17,14,0.15) 35%, rgba(11,17,14,0.4) 70%, rgba(11,17,14,0.98) 100%),
    radial-gradient(circle at center, transparent 40%, rgba(5,8,6,0.6) 100%);
  pointer-events: none;
}

/* Atmospheric Greeting Fade-In */
.fade-in-delayed {
  opacity: 0;
  animation: fadeInSmooth 1.2s cubic-bezier(0.25, 0.1, 0.25, 1) 1s forwards;
  will-change: opacity, transform;
}

@keyframes fadeInSmooth {
  0% {
    opacity: 0;
    transform: translateY(12px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Smooth GPU-Accelerated Cards (Optimized for Mobile Browsers) */
.glass-card {
  background: var(--bg-card);
  border: 1px solid var(--border-ember);
  border-radius: 1.25rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  transition: border-color 0.2s ease, transform 0.2s ease;
  transform: translateZ(0);
}

.glass-card:hover {
  border-color: rgba(232, 165, 88, 0.45);
}

/* Buttons with NO WRAP guarantee for prices! */
.btn-primary-gold {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-family: var(--font-sans);
  font-weight: 800;
  border: none;
  border-radius: 9999px;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(232, 165, 88, 0.35);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-primary-gold:active {
  transform: scale(0.97);
  box-shadow: 0 2px 10px rgba(232, 165, 88, 0.25);
}

.btn-icon-round {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid var(--border-ember);
  background: rgba(232, 165, 88, 0.15);
  color: var(--accent-gold);
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.btn-icon-round:active {
  transform: scale(0.9);
  background: rgba(232, 165, 88, 0.3);
}

/* Clickable Taxi Phone Button */
.btn-taxi {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: #14221c;
  border: 1px solid rgba(96, 165, 250, 0.3);
  border-radius: 1rem;
  color: #60a5fa;
  text-decoration: none;
  font-size: 0.75rem;
  font-weight: 600;
  transition: all 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.btn-taxi:active {
  background: rgba(96, 165, 250, 0.15);
  transform: scale(0.98);
}

/* Category Tabs */
.tab-btn {
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  background: var(--bg-pine);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.tab-btn.active {
  background: linear-gradient(135deg, var(--primary-ember), var(--accent-gold));
  color: #0b110e;
  font-weight: 800;
  border-color: transparent;
  box-shadow: 0 4px 12px rgba(232, 165, 88, 0.3);
}

/* Modals and Drawers */
.modal-overlay,
.drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100svh;
  background: rgba(5, 8, 6, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.25s ease;
  padding: 1rem;
}

.glass-modal {
  background: #121c17;
  border: 1px solid var(--border-ember);
  border-radius: 1.5rem;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8);
  max-height: 90svh;
  overflow-y: auto;
}

.drawer-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 100%;
  max-width: 24rem;
  height: 100%;
  background: #121c17;
  border-left: 1px solid var(--border-ember);
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Utilities */
.hidden { display: none !important; }
.opacity-0 { opacity: 0 !important; }
.pointer-events-none { pointer-events: none !important; }
.pointer-events-auto { pointer-events: auto !important; }

@keyframes bounceSlow {
  0%, 100% { transform: translateY(-25%); animation-timing-function: cubic-bezier(0.8,0,1,1); }
  50% { transform: none; animation-timing-function: cubic-bezier(0,0,0.2,1); }
}
.animate-bounce { animation: bounceSlow 2s infinite; }

@keyframes floatIn {
  0% { opacity: 0; transform: translateY(-10px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.animate-float-in { animation: floatIn 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards; }

import { triggerConfetti } from "./confetti.js";
import { CATALOG_ITEMS, LATE_CHECKOUT_ITEM } from "./catalogData.js";
import { cart } from "./cartManager.js";
import { switchStage } from "./stageManager.js";

let currentCategory = "all";
let currentStage = "1";
let currentSeason = "summer";

// Toast Notification Helper
function showToast(message, title = "🔔 Уведомление") {
  const container = document.getElementById("toastContainer");
  if (!container) return;
  const toast = document.createElement("div");
  toast.className = "glass-card p-3 animate-float-in pointer-events-auto";
  toast.style.cssText = "background: rgba(20,31,25,0.95); border: 1px solid rgba(232,165,88,0.5); color: #f3f4f6; border-radius: 1rem; box-shadow: 0 10px 30px rgba(0,0,0,0.8); font-size: 0.75rem; display: flex; align-items: flex-start; gap: 0.625rem; padding: 0.875rem;";
  toast.innerHTML = `
    <span style="font-size: 20px; margin-top: 2px;">✨</span>
    <div>
      <strong style="color: var(--accent-gold); font-weight: 700; display: block; margin-bottom: 0.125rem;">${title}</strong>
      <p style="color: var(--text-muted); line-height: 1.4;">${message}</p>
    </div>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = "0";
    toast.style.transform = "translateY(-10px)";
    toast.style.transition = "all 0.3s ease";
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// Render Full Catalogue Items List
function renderFullCatalogue(category = "all") {
  const listContainer = document.getElementById("fullCatalogueList");
  if (!listContainer) return;
  listContainer.innerHTML = "";

  const filtered = category === "all" 
    ? CATALOG_ITEMS 
    : CATALOG_ITEMS.filter(i => i.category === category);

  filtered.forEach(product => {
    const card = document.createElement("div");
    card.className = "glass-card p-4";
    card.style.cssText = "padding: 1rem; border-radius: 1.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem;";
    card.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.875rem;">
        <div style="width: 3rem; height: 3rem; border-radius: 1rem; background: rgba(232,165,88,0.1); border: 1px solid rgba(232,165,88,0.2); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0;">
          ${product.icon}
        </div>
        <div>
          <h4 style="font-weight: 700; font-size: 0.875rem; color: #f3f4f6; line-height: 1.3;">${product.displayName}</h4>
          <p style="font-size: 11px; color: var(--text-muted); margin-top: 0.125rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">${product.desc}</p>
        </div>
      </div>
      <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 0.5rem; flex-shrink: 0;">
        <span style="font-size: 0.875rem; font-weight: 800; color: var(--accent-gold); white-space: nowrap;">${product.price.toLocaleString("ru-RU")} ₽</span>
        <button class="btn-add-item btn-primary-gold" style="padding: 0.375rem 0.875rem; font-size: 0.75rem; white-space: nowrap;" data-id="${product.id}">
          + Добавить
        </button>
      </div>
    `;
    listContainer.appendChild(card);
  });

  listContainer.querySelectorAll(".btn-add-item").forEach(btn => {
    btn.addEventListener("click", () => {
      const item = CATALOG_ITEMS.find(i => i.id === btn.dataset.id);
      if (item) {
        if (item.category === "sauna" || item.id.includes("sauna") || item.id.includes("hottub") || item.id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Добавлено в корзину");
        switchStage(currentStage, currentSeason);
      }
    });
  });
}

// Sync Cart UI & Header Badge
function updateCartUI() {
  const count = cart.getTotalCount();
  const total = cart.getTotalPrice();

  const headerBadge = document.getElementById("headerCartCount");
  if (headerBadge) {
    if (count > 0) {
      headerBadge.innerText = count;
      headerBadge.classList.remove("hidden");
      headerBadge.style.display = "flex";
    } else {
      headerBadge.classList.add("hidden");
      headerBadge.style.display = "none";
    }
  }

  const finalTotalEl = document.getElementById("drawerFinalTotal");
  if (finalTotalEl) finalTotalEl.innerText = `${total.toLocaleString("ru-RU")} ₽`;

  const itemsList = document.getElementById("cartItemsList");
  if (!itemsList) return;
  itemsList.innerHTML = "";

  if (cart.getItems().length === 0) {
    itemsList.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; padding: 2rem 0;">Ваша корзина пока пуста</div>`;
  } else {
    cart.getItems().forEach(item => {
      const row = document.createElement("div");
      row.className = "glass-card";
      row.style.cssText = "padding: 0.875rem; border-radius: 1rem; display: flex; align-items: center; justify-content: space-between; border-color: rgba(232,165,88,0.3); gap: 0.5rem;";
      row.innerHTML = `
        <div style="padding-right: 0.5rem; overflow: hidden;">
          <strong style="font-size: 0.75rem; color: #f3f4f6; display: block; line-height: 1.3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.displayName}</strong>
          <span style="font-size: 11px; color: var(--accent-gold); font-weight: 700; margin-top: 0.125rem; display: block;">${item.price.toLocaleString("ru-RU")} ₽ / шт.</span>
        </div>
        <div style="display: flex; align-items: center; gap: 0.5rem; flex-shrink: 0;">
          <button class="btn-minus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">-</button>
          <span style="font-size: 0.75rem; font-weight: 800; width: 1rem; text-align: center;">${item.quantity}</span>
          <button class="btn-plus btn-icon-round" style="width: 1.75rem; height: 1.75rem; font-size: 0.875rem;" data-id="${item.id}">+</button>
        </div>
      `;
      itemsList.appendChild(row);
    });

    itemsList.querySelectorAll(".btn-minus").forEach(b => {
      b.addEventListener("click", () => {
        cart.removeItem(b.dataset.id);
        const hasSaunaLeft = cart.getItems().some(i => i.category === "sauna" || i.id.includes("sauna") || i.id.includes("hottub") || i.id.includes("aroma"));
        if (!hasSaunaLeft) {
          localStorage.removeItem("hasBookedSauna");
        }
        switchStage(currentStage, currentSeason);
      });
    });
    itemsList.querySelectorAll(".btn-plus").forEach(b => {
      b.addEventListener("click", () => {
        const item = cart.getItems().find(i => i.id === b.dataset.id);
        if (item) cart.addItem(item);
      });
    });
  }
}

// Initialize Application
document.addEventListener("DOMContentLoaded", () => {
  renderFullCatalogue("all");

  cart.subscribe(() => updateCartUI());
  updateCartUI();

  // Quick Order Add Buttons
  document.querySelectorAll(".btn-quick-add").forEach(btn => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.id;
      let item = CATALOG_ITEMS.find(i => i.id === id);
      if (id === "late-checkout-16") item = LATE_CHECKOUT_ITEM;
      if (id === "coffee-croissant") {
        item = { id: "coffee-croissant", displayName: "☕ Свежий кофе и круассаны в домик", price: 550, category: "service", fiscalName: "Услуги организации питания в номере" };
      }
      if (item) {
        if (item.category === "sauna" || id.includes("sauna") || id.includes("hottub") || id.includes("aroma")) {
          localStorage.setItem("hasBookedSauna", "true");
        }
        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
        switchStage(currentStage, currentSeason);
      }
    });
  });

  // Edit booked sauna button
  const editSaunaBtn = document.getElementById("showSaunaCarouselBtn");
  if (editSaunaBtn) {
    editSaunaBtn.addEventListener("click", () => {
      const saunaBookedBanner = document.getElementById("saunaBookedBanner");
      const saunaSection = document.getElementById("saunaSection");
      if (saunaBookedBanner) saunaBookedBanner.classList.add("hidden");
      if (saunaSection) {
        saunaSection.classList.remove("hidden");
        saunaSection.scrollIntoView({ behavior: "smooth" });
      }
    });
  }

  // Developer Menu Controls & Auto-Close
  const toggleDemoBtn = document.getElementById("toggleDemoMenuBtn");
  const demoPanel = document.getElementById("demoMenuPanel");
  const closeDemoPanelBtn = document.getElementById("closeDemoPanelBtn");

  if (toggleDemoBtn && demoPanel) {
    toggleDemoBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      demoPanel.classList.toggle("hidden");
    });
  }

  if (closeDemoPanelBtn && demoPanel) {
    closeDemoPanelBtn.addEventListener("click", () => {
      demoPanel.classList.add("hidden");
    });
  }

  // Tap anywhere outside developer panel to close it!
  document.addEventListener("click", (e) => {
    if (demoPanel && !demoPanel.classList.contains("hidden")) {
      if (!demoPanel.contains(e.target) && e.target !== toggleDemoBtn) {
        demoPanel.classList.add("hidden");
      }
    }
  });

  // Read Stage from URL or localStorage
  const urlParams = new URLSearchParams(window.location.search);
  const savedStage = urlParams.get("stage") || localStorage.getItem("demoStage") || "1";

  currentStage = savedStage;
  const stageSelector = document.getElementById("stageSelector");
  if (stageSelector) stageSelector.value = currentStage;

  // Initial stage application
  switchStage(currentStage, currentSeason, (bannerConfig) => {
    if (bannerConfig.actionCategory) {
      const catBtn = document.querySelector(`.tab-btn[data-cat="${bannerConfig.actionCategory}"]`);
      if (catBtn) catBtn.click();
      const catalogEl = document.getElementById("fullCatalogueList");
      if (catalogEl) catalogEl.scrollIntoView({ behavior: "smooth" });
    } else if (bannerConfig.actionModal) {
      openModal(bannerConfig.actionModal);
    } else if (bannerConfig.actionItem === "late-checkout-16") {
      cart.addItem(LATE_CHECKOUT_ITEM);
      openDrawer("cartDrawer");
      showToast("Поздний выезд до 16:00 добавлен в корзину", "⏳ Продление проживания");
    }
  });

  // FULL PAGE RELOAD ON STAGE CHANGE (Per user request!)
  if (stageSelector) {
    stageSelector.addEventListener("change", () => {
      const newStage = stageSelector.value;
      localStorage.setItem("demoStage", newStage);
      if (demoPanel) demoPanel.classList.add("hidden");

      // Perform full browser page reload with query param
      window.location.search = `?stage=${newStage}`;
    });
  }

  // Category Tabs Filter
  document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      currentCategory = btn.dataset.cat;
      renderFullCatalogue(currentCategory);
    });
  });

  // Drawers & Modals Control
  const openDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(0)";
  };

  const closeDrawer = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".drawer-panel");
    if (child) child.style.transform = "translateX(100%)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 250);
  };

  const openModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("opacity-0", "pointer-events-none");
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(1)";
  };

  const closeModal = (id) => {
    const el = document.getElementById(id);
    if (!el) return;
    const child = el.querySelector(".glass-modal");
    if (child) child.style.transform = "scale(0.95)";
    setTimeout(() => {
      el.classList.add("opacity-0", "pointer-events-none");
    }, 200);
  };

  // Background Tap-to-Close for Modals
  document.querySelectorAll(".modal-overlay, .drawer-overlay").forEach(overlay => {
    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) {
        const id = overlay.id;
        if (overlay.classList.contains("modal-overlay")) {
          closeModal(id);
        } else {
          closeDrawer(id);
        }
      }
    });
  });

  // Explicit Bottom Close Buttons
  document.querySelectorAll(".btn-close-modal-bottom").forEach(btn => {
    btn.addEventListener("click", () => {
      const modalId = btn.dataset.modal;
      if (modalId) closeModal(modalId);
    });
  });

  // Header Cart Button
  const openCartHeaderBtn = document.getElementById("openCartHeaderBtn");
  const closeCartBtn = document.getElementById("closeCartBtn");
  if (openCartHeaderBtn) openCartHeaderBtn.addEventListener("click", () => openDrawer("cartDrawer"));
  if (closeCartBtn) closeCartBtn.addEventListener("click", () => closeDrawer("cartDrawer"));

  // Top X Close Buttons
  const closeGuideBtn = document.getElementById("closeGuideBtn");
  if (closeGuideBtn) closeGuideBtn.addEventListener("click", () => closeModal("guideModal"));

  const closeRegBtn = document.getElementById("closeRegBtn");
  if (closeRegBtn) closeRegBtn.addEventListener("click", () => closeModal("regModal"));

  const closeOrmBtn = document.getElementById("closeOrmBtn");
  if (closeOrmBtn) closeOrmBtn.addEventListener("click", () => closeModal("ormModal"));

  // Online Registration Form Submission
  const submitRegBtn = document.getElementById("submitRegBtn");
  if (submitRegBtn) {
    submitRegBtn.addEventListener("click", () => {
      const phone = document.getElementById("regPhone")?.value;
      if (!phone || phone.trim() === "") {
        showToast("Укажите ваш контактный телефон для связи", "⚠️ Внимание");
        return;
      }
      showToast("✅ Онлайн-регистрация завершена, Ирина! Пропуск на въезд для вашего автомобиля оформлен.", "📋 Добро пожаловать");
      closeModal("regModal");
    });
  }

  // Wi-Fi Copy Button (Password: 11111111)
  const copyWifiBtn = document.getElementById("copyWifiBtn");
  if (copyWifiBtn) {
    copyWifiBtn.addEventListener("click", () => {
      navigator.clipboard.writeText("11111111");
      showToast("Пароль 11111111 скопирован в буфер обмена", "📡 Wi-Fi подключение");
    });
  }

  // Housekeeping Rating Stars
  const hkStars = document.querySelectorAll(".hk-star");
  const hkFeedbackBox = document.getElementById("hkFeedbackBox");
  const submitHkBtn = document.getElementById("submitHkBtn");

  hkStars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      hkStars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });
      if (rating >= 4) {
        if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
        triggerConfetti();
        showToast("🎉 Спасибо за высокую оценку чистоты! Передали благодарность нашей горничной Ладога Парк.", "✨ Отличная уборка");
      } else {
        if (hkFeedbackBox) hkFeedbackBox.classList.remove("hidden");
      }
    });
  });

  if (submitHkBtn) {
    submitHkBtn.addEventListener("click", () => {
      const text = document.getElementById("hkText")?.value;
      if (!text || text.trim() === "") {
        showToast("Напишите, что нам исправить в номере", "⚠️ Внимание");
        return;
      }
      showToast("Ваше замечание по уборке отправлено лично управляющему. Сейчас всё исправим!", "🙏 Спасибо за сигнал");
      if (hkFeedbackBox) hkFeedbackBox.classList.add("hidden");
    });
  }

  // ORM Interactive Rating Stars
  const stars = document.querySelectorAll(".star-btn");
  const lowForm = document.getElementById("lowRatingForm");
  const highCard = document.getElementById("highRatingCard");

  stars.forEach(star => {
    star.addEventListener("click", () => {
      const rating = parseInt(star.dataset.star, 10);
      stars.forEach(s => {
        if (parseInt(s.dataset.star, 10) <= rating) {
          s.style.color = "var(--accent-gold)";
          s.style.transform = "scale(1.15)";
        } else {
          s.style.color = "#4b5563";
          s.style.transform = "scale(1)";
        }
      });

      if (rating >= 4) {
        if (lowForm) lowForm.classList.add("hidden");
        if (highCard) {
          highCard.classList.remove("hidden");
          highCard.classList.add("animate-fade-in");
        }
