      } else {
        showToast(`Заказ на сумму ${total.toLocaleString("ru-RU")} ₽ добавлен в ваш фолио TravelLine. Оплата при выезде.`, "🏨 Фолио обновлено");
      }
      cart.clearCart();
      closeDrawer("cartDrawer");
