  }

  // Support FAB Button
  const fabSupportBtn = document.getElementById("fabSupportBtn");
  if (fabSupportBtn) {
    fabSupportBtn.addEventListener("click", () => {
      showToast("Связь с консьерж-сервисом Ладога Парк: +7 (812) 555-01-26 (Круглосуточно)", "📞 Консьерж на связи");
    });
