}

.v2-luxe-main {
  max-width: 44rem;
  margin: -1.5rem auto 0;
  padding: 0 1.25rem;
  position: relative;
  z-index: 30;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* High-End Surface Cards */
.v2-luxe-card {
  background: #FFFFFF;
  border-radius: 1.75rem;
  padding: 1.5rem;
  border: 1px solid rgba(26, 36, 30, 0.06);
  box-shadow: 0 12px 28px -6px rgba(26, 36, 30, 0.05), 0 4px 10px -2px rgba(26, 36, 30, 0.02);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.v2-luxe-card:hover {
  box-shadow: 0 20px 36px -8px rgba(26, 36, 30, 0.09), 0 6px 14px -2px rgba(26, 36, 30, 0.04);
  border-color: rgba(197, 160, 89, 0.3);
}

/* VIP Black Gold Access Card (Gate & Wi-Fi) */
.v2-vip-access-card {
  background: linear-gradient(135deg, #1A241E 0%, #0D1310 100%);
  border-radius: 1.75rem;
  padding: 1.5rem;
  color: #FFFFFF;
  border: 1px solid rgba(197, 160, 89, 0.35);
  box-shadow: 0 20px 40px -10px rgba(13, 19, 16, 0.5), 0 0 20px rgba(197, 160, 89, 0.1);
  position: relative;
  overflow: hidden;
}

.v2-vip-access-card::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -50%;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, rgba(197, 160, 89, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

/* Boutique Buttons */
.v2-luxe-btn-primary {
  background: linear-gradient(135deg, #1A241E 0%, #28382F 100%);
  color: #FFFFFF;
  font-family: 'Manrope', sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
