  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  text-decoration: none;
  width: 100%;
}

.v2-luxe-btn-gold:hover, .v2-luxe-btn-gold:active {
  transform: translateY(-2px);
  box-shadow: 0 12px 28px -4px rgba(197, 160, 89, 0.5);
}

.v2-luxe-btn-outline {
  background: transparent;
  color: #1A241E;
  font-weight: 700;
  font-size: 0.8rem;
  padding: 0.75rem 1.25rem;
  border-radius: 1rem;
