.v2-luxe-btn-outline:hover {
  background: rgba(26, 36, 30, 0.05);
}

/* Horizontal Scroll Carousels */
.v2-luxe-carousel {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: 0.75rem;
  margin: 0 -0.5rem;
