  border: 1px solid rgba(26, 36, 30, 0.06);
  box-shadow: 0 8px 20px -6px rgba(26, 36, 30, 0.05);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.v2-luxe-addon-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 28px -6px rgba(26, 36, 30, 0.1);
  border-color: rgba(197, 160, 89, 0.4);
}

.v2-luxe-addon-img {
  height: 110px;
  width: 100%;
  object-fit: cover;
  position: relative;
}

/* Apple-Style Floating Dock Bottom Nav */
.v2-luxe-dock {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%);
