  max-width: 26rem;
  height: 4.25rem;
  background: rgba(26, 36, 30, 0.88);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 9999px;
  box-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.5), 0 0 20px rgba(26, 36, 30, 0.3);
  display: flex;
  justify-content: space-around;
  align-items: center;
  z-index: 50;
  padding: 0 0.75rem;
}

.v2-luxe-dock-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.2rem;
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  padding: 0.35rem 0.75rem;
  border-radius: 9999px;
  position: relative;
}

.v2-luxe-dock-item.active {
  color: #E4CA92;
  font-weight: 800;
  transform: translateY(-2px);
}

.v2-luxe-dock-item.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  width: 4px;
  height: 4px;
  border-radius: 9999px;
  background: #E4CA92;
  box-shadow: 0 0 8px #E4CA92;
}

.v2-luxe-dock-item:active {
  transform: scale(0.92);
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

