      if (item) {
        if (item.category === "sauna" || id.includes("sauna") || id.includes("hottub") || id.includes("aroma")) {
          pendingSaunaItem = item;
          openSaunaTimeModal(item);
          return;
        }

        cart.addItem(item);
        showToast(`«${item.displayName}» добавлен в ваш заказ`, "✨ Корзина обновлена");
        switchStage(currentStage, currentSeason);
      }
    });
  });

  // Modal logic
  function openSaunaTimeModal(item) {
    const modal = document.getElementById("saunaTimeModal");
    const title = document.getElementById("saunaTimeModalTitle");
    const slotsContainer = document.getElementById("saunaTimeSlots");
    if (!modal) return;

    title.innerText = `Время: ${item.displayName}`;
    slotsContainer.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.75rem; grid-column: span 3; padding: 1rem;">Загрузка свободного времени из TravelLine...</div>`;

    modal.classList.remove("opacity-0", "pointer-events-none");
    modal.querySelector(".glass-modal").style.transform = "scale(1)";

    // Fetch from backend proxy
    fetch("http://132.243.17.20:3000/api/saunas/availability")
      .then(r => r.json())
      .then(res => {
         if (res.success && res.data) {
           renderTimeSlots(res.data);
         } else {
           slotsContainer.innerHTML = `<div style="text-align: center; color: #ef4444; font-size: 0.75rem; grid-column: span 3; padding: 1rem;">Ошибка загрузки времени</div>`;
         }
      })
      .catch(err => {
         console.warn("TravelLine proxy unavailable, using fallback mock slots.");
         const mockSlots = ['12:00', '14:00', '16:00', '18:00', '20:00', '22:00'].map(t => ({time: t, available: Math.random() > 0.3}));
         renderTimeSlots(mockSlots);
      });
  }

  function renderTimeSlots(slots) {
    const slotsContainer = document.getElementById("saunaTimeSlots");
    slotsContainer.innerHTML = "";
    slots.forEach(slot => {
      const btn = document.createElement("button");
      btn.innerText = slot.time;
      if (slot.available) {
        btn.style.cssText = "background: rgba(232,165,88,0.1); border: 1px solid rgba(232,165,88,0.3); color: var(--accent-gold); padding: 0.75rem; border-radius: 0.75rem; font-weight: 700; font-size: 0.875rem; cursor: pointer; transition: all 0.2s;";
        btn.onclick = () => {
           localStorage.setItem("hasBookedSauna", "true");
           const timeItem = {...pendingSaunaItem, displayName: `${pendingSaunaItem.displayName} (${slot.time})`, id: `${pendingSaunaItem.id}-${slot.time}`};
           cart.addItem(timeItem);
           showToast(`«${timeItem.displayName}» добавлено`, "✨ Время забронировано");
           switchStage(currentStage, currentSeason);
           closeSaunaModal();
        };
      } else {
        btn.style.cssText = "background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); color: var(--text-muted); padding: 0.75rem; border-radius: 0.75rem; font-weight: 600; font-size: 0.875rem; cursor: not-allowed; opacity: 0.5;";
        btn.disabled = true;
      }
      slotsContainer.appendChild(btn);
    });
  }

  function closeSaunaModal() {
    const modal = document.getElementById("saunaTimeModal");
    if (!modal) return;
    modal.classList.add("opacity-0", "pointer-events-none");
    modal.querySelector(".glass-modal").style.transform = "scale(0.95)";
    pendingSaunaItem = null;
  }

  document.querySelectorAll(".btn-close-sauna").forEach(btn => {
    btn.addEventListener("click", closeSaunaModal);
  });
});

